                        for (int k = 1; k < call_argc; k++) JS_FreeValue(ctx, (JSValue)call_argv[k]);  /* args array + any extra operands */
                        ((JSValue *)call_argv)[-2] = genv;
                        ((JSValue *)call_argv)[-1] = gnext;
