                    free_arg_list(ctx, atab3, alen3);
                    if (unlikely(JS_IsException(ret_val))) goto exception;
                    cargv3 = sp - ca3;
                    for (i = cf3; i < ca3; i++) JS_FreeValue(ctx, cargv3[i]);
                    sp += cf3 - ca3;
