                    con_from_super = 1; con_super_ref = super;   /* owned; freed in the CONT_CONSTRUCT return/unwind */
                    tramp_first = 0; tramp_is_tail = 0;   /* caller_sp = current sp: super() pushes its object there */
                    goto do_construct_tramp;
