/* Every step state MUST begin with JSStepHdr — the driver casts the opaque state to JSStepHdr * and writes
   def/orig_c* through it, so a state that forgets gets its first field overwritten by the step-def pointer.
   That bug has now happened THREE times (JSArrayFind, JSArrayEvery, JSArraySort) and each time the corruption
   surfaced far from the cause: the last one showed up as s->obj holding &js_array_sort_def, and I misread it
   twice as a sort-semantics mismatch. A comment saying "MUST be first" did not prevent any of the three. This
   does, at compile time. Adding a state to js_tramp_step_defs without a line here is itself the omission. */
#define STEP_STATE_HDR_FIRST(T) \
    _Static_assert(offsetof(T, hdr) == 0, #T " must begin with JSStepHdr (the step driver casts to it)")
STEP_STATE_HDR_FIRST(JSArrayFind);
STEP_STATE_HDR_FIRST(JSArrayEvery);
STEP_STATE_HDR_FIRST(JSArrayReduce);
STEP_STATE_HDR_FIRST(JSArraySort);
STEP_STATE_HDR_FIRST(JSStrReplace);
STEP_STATE_HDR_FIRST(JSReRep);
STEP_STATE_HDR_FIRST(JSJsonReviver);
STEP_STATE_HDR_FIRST(JSStrCtor);
STEP_STATE_HDR_FIRST(JSStrConcat);
STEP_STATE_HDR_FIRST(JSTASlice);
STEP_STATE_HDR_FIRST(JSArrayAt);
STEP_STATE_HDR_FIRST(JSArraySearch);
STEP_STATE_HDR_FIRST(JSStrRecv);
STEP_STATE_HDR_FIRST(JSTAIdx);
STEP_STATE_HDR_FIRST(JSJsonRaw);
STEP_STATE_HDR_FIRST(JSObjDefProp);
STEP_STATE_HDR_FIRST(JSParseNum);
STEP_STATE_HDR_FIRST(JSStrSplit);
STEP_STATE_HDR_FIRST(JSArrayJoin);
STEP_STATE_HDR_FIRST(JSArrayToString);
STEP_STATE_HDR_FIRST(JSFuncCall);
STEP_STATE_HDR_FIRST(JSCoerce1);
STEP_STATE_HDR_FIRST(JSNumberFmt);
STEP_STATE_HDR_FIRST(JSNumCtor);
STEP_STATE_HDR_FIRST(JSPrimArgs);

static const JSTrampStepDef *tramp_step_def_of(JSValueConst func)
{
    JSObject *fp;
    if (JS_VALUE_GET_TAG(func) != JS_TAG_OBJECT) return NULL;
    fp = JS_VALUE_GET_OBJ(func);
    if (fp->class_id == JS_CLASS_C_FUNCTION_DATA) {
        /* a closure (Promise reaction) that DECLARED itself a step machine — its step_def, or NULL for an ordinary
           closure. The closure is then driven through the SAME do_step_tramp path as a C-function step machine, so
           an internal JS_Call to a user resolve/reject runs on the tramp and parks. */
        JSCFunctionDataRecord *s = fp->u.c_function_data_record;
        return s ? s->step_def : NULL;
    }
    if (fp->class_id != JS_CLASS_C_FUNCTION) return NULL;
    if (fp->u.cfunc.cproto != JS_CFUNC_step && fp->u.cfunc.cproto != JS_CFUNC_step_ctor) return NULL;
    DCHECK((unsigned)fp->u.cfunc.magic < STEPDEF_COUNT, "JS_CFUNC_STEP_DEF id is out of range");
    DCHECK(js_tramp_step_defs[fp->u.cfunc.magic] != NULL, "STEPDEF id has no table row");
    return js_tramp_step_defs[fp->u.cfunc.magic];
}

/* 23.1.3.36 Array.prototype.toString. Stages: 0 ToObject, 1 Get(array,"join"), 2 its dispatch, 3 the result. */
static int js_array_tostring_step(JSContext *ctx, void *st, JSValue cb_result, JSValue **out_cb, int *out_argc)
{
    JSArrayToString *s = st;
    int r;

    if (s->hdr.stage == 0) {
        JS_FreeValue(ctx, cb_result); cb_result = JS_UNDEFINED;
        s->obj = JS_ToObject(ctx, s->hdr.this_val);
        s->result = JS_UNDEFINED;
        if (JS_IsException(s->obj)) { s->obj = JS_UNDEFINED; return -1; }
        s->hdr.stage = 1;
    }
    if (s->hdr.stage == 1) {
        r = step_getprop_run(ctx, &s->hdr, s->obj, JS_ATOM_join, cb_result, &s->cb[1], out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->hdr.stage = 2;
    }
    if (s->hdr.stage == 2) {
        if (!JS_IsFunction(ctx, s->cb[1])) {
            /* step 3: a non-callable `join` falls back to the intrinsic Object.prototype.toString, which reads
               only @@toStringTag — a read the spec performs, and one this machine does not yet route. */
            s->result = js_object_toString(ctx, s->obj, 0, NULL);
            return JS_IsException(s->result) ? -1 : 0;
        }
        s->cb[0] = js_dup(s->obj);
        s->hdr.stage = 3;
        *out_cb = s->cb; *out_argc = 0;
        return 3;
    }
    DCHECK(s->hdr.stage == 3, "Array.prototype.toString: unknown stage");
    s->result = cb_result;
    return 0;
}

static JSValue js_array_tostring_fini(JSContext *ctx, void *st, bool take_result)
{
    JSArrayToString *s = st;
    JSValue r = take_result ? s->result : JS_UNDEFINED;
    int i;
    if (!take_result) JS_FreeValue(ctx, s->result);
    JS_FreeValue(ctx, s->obj);
    for (i = 0; i < 2; i++) JS_FreeValue(ctx, s->cb[i]);
    js_free(ctx, s);
    return r;
}

/* 23.1.3.18 join / 23.1.3.33 toLocaleString. Stages: 0 ToObject, 1 LengthOfArrayLike, 2 ToString(separator),
   then the loop — 3 its head (the separator), 8 read element i, 4 dispatch on it, 5 the toLocaleString method,
   6 its call's result, 7 ToString(element) and append. The loop returns to 3 until i reaches len. */
static int js_array_join_step(JSContext *ctx, void *st, JSValue cb_result, JSValue **out_cb, int *out_argc)
{
    JSArrayJoin *s = st;
    int mode = s->hdr.arg;
    int locale = (mode == JOIN_ARRAY_LOCALE || mode == JOIN_TA_LOCALE);
    int is_ta = (mode == JOIN_TA || mode == JOIN_TA_LOCALE);
    JSValue str;
    int r;

    if (s->hdr.stage == 0) {
        JS_FreeValue(ctx, cb_result); cb_result = JS_UNDEFINED;
        /* FIRST, before anything that can throw: the teardown frees exactly what the state holds. */
        string_buffer_init(ctx, &s->b, 0);
        s->sep = JS_UNDEFINED; s->el = JS_UNDEFINED; s->result = JS_UNDEFINED;
        if (is_ta) {
            JSObject *p = get_typed_array(ctx, s->hdr.this_val);
            if (!p) { s->obj = JS_UNDEFINED; return -1; }
            if (typed_array_is_oob(p)) {
                s->obj = JS_UNDEFINED;
                JS_ThrowTypeErrorArrayBufferOOB(ctx);
                return -1;
            }
            s->obj = js_dup(s->hdr.this_val);
            s->oldlen = s->len = p->u.array.count;
        } else {
            s->obj = JS_ToObject(ctx, s->hdr.this_val);
            if (JS_IsException(s->obj)) { s->obj = JS_UNDEFINED; return -1; }
        }
        s->hdr.stage = 1;
    }
    if (s->hdr.stage == 1) {
        if (!is_ta) {   /* a typed array's length is its own count, not a property read */
            r = step_length_run(ctx, &s->hdr, s->obj, cb_result, &s->len, out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
        }
        s->hdr.stage = 2;
    }
    if (s->hdr.stage == 2) {
        /* toLocaleString takes no separator: its comma is not configurable. */
        if (!locale && s->hdr.argc > 0 && !JS_IsUndefined(s->hdr.argv[0])) {
            r = step_tostring_run(ctx, &s->hdr, s->hdr.argv[0], cb_result, &s->sep, out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
            if (is_ta) {
                /* ToString(separator) can DETACH or shrink the buffer, so the count is re-read after it and the
                   walk covers only what survived. s->oldlen still holds the count from before, and the tail
                   below emits the separators the lost elements would have contributed — which is exactly what a
                   resize is observable as. */
                int64_t newlen = JS_VALUE_GET_OBJ(s->obj)->u.array.count;
                if (newlen < s->len) s->len = newlen;
            }
        }
        s->i = 0;
        s->hdr.stage = 3;
    }

    for (;;) {
        if (s->hdr.stage == 3) {
            /* the loop HEAD is its own stage precisely because it writes to the buffer: the read below suspends
               and re-enters this function at its own stage, so a separator emitted in the same block as the read
               would be emitted again on every resume — which under forced preemption is every element. */
            if (s->i >= s->len)
                break;
            if (s->i > 0) {
                if (JS_IsUndefined(s->sep)) {
                    string_buffer_putc8(&s->b, ',');
                } else {
                    JSString *p = JS_VALUE_GET_STRING(s->sep);   /* re-derived: a C local would be gone */
                    string_buffer_concat(&s->b, p, 0, p->len);
                }
            }
            s->hdr.stage = 8;
        }
        if (s->hdr.stage == 8) {
            r = step_getidx_run(ctx, &s->hdr, s->obj, s->i, cb_result, &s->el, out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
            s->hdr.stage = 4;
        }
        if (s->hdr.stage == 4) {
            if (JS_IsNull(s->el) || JS_IsUndefined(s->el)) {
                /* a hole or a nullish element contributes nothing but the separator */
                JS_FreeValue(ctx, s->el); s->el = JS_UNDEFINED;
                s->i++;
                s->hdr.stage = 3;
                continue;
            }
            s->hdr.stage = locale ? 5 : 7;
        }
        if (s->hdr.stage == 5) {
            r = step_getprop_run(ctx, &s->hdr, s->el, JS_ATOM_toLocaleString, cb_result, &s->cb[1],
                                 out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
            s->cb[0] = s->el;                 /* the receiver: ownership moves into the call buffer */
            s->el = JS_UNDEFINED;
            s->hdr.stage = 6;
            *out_cb = s->cb; *out_argc = 0;
            return 3;                          /* a non-callable toLocaleString throws HERE, as Invoke does */
        }
        if (s->hdr.stage == 6) {
            s->el = cb_result; cb_result = JS_UNDEFINED;
            JS_FreeValue(ctx, s->cb[0]); s->cb[0] = JS_UNDEFINED;
            JS_FreeValue(ctx, s->cb[1]); s->cb[1] = JS_UNDEFINED;
            s->hdr.stage = 7;
        }
        DCHECK(s->hdr.stage == 7, "Array.prototype.join: unknown stage");
        r = step_tostring_run(ctx, &s->hdr, s->el, cb_result, &str, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        JS_FreeValue(ctx, s->el); s->el = JS_UNDEFINED;
        if (string_buffer_concat_value_free(&s->b, str))
            return -1;
        s->i++;
        s->hdr.stage = 3;
    }

    JS_FreeValue(ctx, cb_result);
    if (is_ta) {
        /* the separators for the elements a resizing separator-coercion removed */
        for (s->i = s->len > 1 ? s->len : 1; s->i < s->oldlen; s->i++) {
            if (JS_IsUndefined(s->sep)) {
                string_buffer_putc8(&s->b, ',');
            } else {
                JSString *p = JS_VALUE_GET_STRING(s->sep);
                string_buffer_concat(&s->b, p, 0, p->len);
            }
        }
    }
    /* string_buffer_end NULLs the buffer on every path that consumed it and leaves it intact on the error
       path, so the teardown's string_buffer_free is right either way. */
    s->result = string_buffer_end(&s->b);
    return JS_IsException(s->result) ? -1 : 0;
}

static JSValue js_array_join_fini(JSContext *ctx, void *st, bool take_result)
{
    JSArrayJoin *s = st;
    JSValue r = take_result ? s->result : JS_UNDEFINED;
    int i;
    DCHECK(s->b.ctx != NULL, "the join buffer is initialised by stage 0's first statement, before any throw");
    string_buffer_free(&s->b);
    if (!take_result) JS_FreeValue(ctx, s->result);
    JS_FreeValue(ctx, s->obj);
    JS_FreeValue(ctx, s->sep);
    JS_FreeValue(ctx, s->el);
    for (i = 0; i < 2; i++) JS_FreeValue(ctx, s->cb[i]);
    js_free(ctx, s);
    return r;
}

static JSValue js_array_pop(JSContext *ctx, JSValueConst this_val,
                            int argc, JSValueConst *argv, int shift)
{
    JSValue obj, res = JS_UNDEFINED;
    int64_t len, newLen;
    JSValue *arrp;
    uint32_t count32;

    obj = JS_ToObject(ctx, this_val);
    if (js_get_length64(ctx, &len, obj))
        goto exception;
    newLen = 0;
    if (len > 0) {
        newLen = len - 1;
        /* Special case fast arrays */
        if (js_get_fast_array(ctx, obj, &arrp, &count32) && count32 == len) {
            JSObject *p = JS_VALUE_GET_OBJ(obj);
            if (shift) {
                res = arrp[0];
                memmove(arrp, arrp + 1, (count32 - 1) * sizeof(*arrp));
                p->u.array.count--;
            } else {
                res = arrp[count32 - 1];
                p->u.array.count--;
            }
        } else {
            if (shift) {
                res = JS_GetPropertyInt64(ctx, obj, 0);
                if (JS_IsException(res))
                    goto exception;
                if (JS_CopySubArray(ctx, obj, 0, 1, len - 1, +1))
                    goto exception;
            } else {
                res = JS_GetPropertyInt64(ctx, obj, newLen);
                if (JS_IsException(res))
                    goto exception;
            }
            if (JS_DeletePropertyInt64(ctx, obj, newLen, JS_PROP_THROW) < 0)
                goto exception;
        }
    }
    if (JS_SetProperty(ctx, obj, JS_ATOM_length, js_int64(newLen)) < 0)
        goto exception;

    JS_FreeValue(ctx, obj);
    return res;

 exception:
    JS_FreeValue(ctx, res);
    JS_FreeValue(ctx, obj);
    return JS_EXCEPTION;
}

static JSValue js_array_push(JSContext *ctx, JSValueConst this_val,
                             int argc, JSValueConst *argv, int unshift)
{
    JSValue obj;
    int i;
    int64_t len, from, newLen;

    /* fast path for push on fast arrays */
    if (likely(JS_VALUE_GET_TAG(this_val) == JS_TAG_OBJECT && !unshift)) {
        JSObject *p = JS_VALUE_GET_OBJ(this_val);
        if (likely(p->class_id == JS_CLASS_ARRAY &&
                   p->fast_array &&
                   p->extensible &&
                   p->shape->proto == JS_VALUE_GET_OBJ(ctx->class_proto[JS_CLASS_ARRAY]) &&
                   ctx->std_array_prototype)) {
            uint32_t array_len, new_len;
            if (likely(JS_VALUE_GET_TAG(p->prop[0].u.value) == JS_TAG_INT &&
                       (get_shape_prop(p->shape)->flags & JS_PROP_WRITABLE))) {
                array_len = JS_VALUE_GET_INT(p->prop[0].u.value);
                new_len = array_len + argc;
                if (likely(array_len == p->u.array.count &&
                           new_len >= array_len && new_len <= (uint32_t)INT32_MAX)) { /* no overflow and within fast-array bounds */
                    if (unlikely(new_len > p->u.array.u1.size)) {
                        if (expand_fast_array(ctx, p, new_len))
                            return JS_EXCEPTION;
                    }
                    /* Forced-exec COW: this fast path writes values[] directly (bypassing add_fast_array_element's
                       capture), so record each created element slot so a shared array's per-flow push is isolated
                       (cow_unapply truncates it away). O(1) append capture; cheap-skips a flow_local array. */
                    for(i = 0; i < argc; i++)
                        cow_capture_append(ctx, this_val, __JS_AtomFromUInt32(array_len + i));
                    for(i = 0; i < argc; i++) {
                        p->u.array.u.values[array_len + i] = js_dup(argv[i]);
                    }
                    p->u.array.count = new_len;
                    p->prop[0].u.value = js_uint32(new_len);
                    return js_int32(new_len);
                }
            }
        }
    }

    obj = JS_ToObject(ctx, this_val);
    if (js_get_length64(ctx, &len, obj))
        goto exception;
    newLen = len + argc;
    if (newLen > MAX_SAFE_INTEGER) {
        JS_ThrowTypeError(ctx, "Array loo long");
        goto exception;
    }
    from = len;
    if (unshift && argc > 0) {
        if (JS_CopySubArray(ctx, obj, argc, 0, len, -1))
            goto exception;
        from = 0;
    }
    for(i = 0; i < argc; i++) {
        if (JS_SetPropertyInt64(ctx, obj, from + i, js_dup(argv[i])) < 0)
            goto exception;
    }
    if (JS_SetProperty(ctx, obj, JS_ATOM_length, js_int64(newLen)) < 0)
        goto exception;

    JS_FreeValue(ctx, obj);
    return js_int64(newLen);

 exception:
    JS_FreeValue(ctx, obj);
    return JS_EXCEPTION;
}

static JSValue js_array_reverse(JSContext *ctx, JSValueConst this_val,
                                int argc, JSValueConst *argv)
{
    JSValue obj, lval, hval;
    JSValue *arrp;
    int64_t len, l, h;
    int l_present, h_present;
    uint32_t count32;

    lval = JS_UNDEFINED;
    obj = JS_ToObject(ctx, this_val);
    if (js_get_length64(ctx, &len, obj))
        goto exception;

    /* Special case fast arrays */
    if (js_get_fast_array(ctx, obj, &arrp, &count32) && count32 == len) {
        uint32_t ll, hh;

        if (count32 > 1) {
            for (ll = 0, hh = count32 - 1; ll < hh; ll++, hh--) {
                lval = arrp[ll];
                arrp[ll] = arrp[hh];
                arrp[hh] = lval;
            }
        }
        return obj;
    }

    for (l = 0, h = len - 1; l < h; l++, h--) {
        l_present = JS_TryGetPropertyInt64(ctx, obj, l, &lval);
        if (l_present < 0)
            goto exception;
        h_present = JS_TryGetPropertyInt64(ctx, obj, h, &hval);
        if (h_present < 0)
            goto exception;
        if (h_present) {
            if (JS_SetPropertyInt64(ctx, obj, l, hval) < 0)
                goto exception;

            if (l_present) {
                if (JS_SetPropertyInt64(ctx, obj, h, lval) < 0) {
                    lval = JS_UNDEFINED;
                    goto exception;
                }
                lval = JS_UNDEFINED;
            } else {
                if (JS_DeletePropertyInt64(ctx, obj, h, JS_PROP_THROW) < 0)
                    goto exception;
            }
        } else {
            if (l_present) {
                if (JS_DeletePropertyInt64(ctx, obj, l, JS_PROP_THROW) < 0)
                    goto exception;
                if (JS_SetPropertyInt64(ctx, obj, h, lval) < 0) {
                    lval = JS_UNDEFINED;
                    goto exception;
                }
                lval = JS_UNDEFINED;
            }
        }
    }
    return obj;

 exception:
    JS_FreeValue(ctx, lval);
    JS_FreeValue(ctx, obj);
    return JS_EXCEPTION;
}

// Note: a.toReversed() is a.slice().reverse() with the twist that a.slice()
// leaves holes in sparse arrays intact whereas a.toReversed() replaces them
// with undefined, thus in effect creating a dense array.
// Does not use Array[@@species], always returns a base Array.
static JSValue js_array_toReversed(JSContext *ctx, JSValueConst this_val,
                                   int argc, JSValueConst *argv)
{
    JSValue arr, obj, ret, *arrp, *pval;
    JSObject *p;
    int64_t i, len;
    uint32_t count32;

    ret = JS_EXCEPTION;
    arr = JS_UNDEFINED;
    obj = JS_ToObject(ctx, this_val);
    if (js_get_length64(ctx, &len, obj))
        goto exception;

    arr = js_allocate_fast_array(ctx, len);
    if (JS_IsException(arr))
        goto exception;

    if (len > 0) {
        p = JS_VALUE_GET_OBJ(arr);

        i = len - 1;
        pval = p->u.array.u.values;
        if (js_get_fast_array(ctx, obj, &arrp, &count32) && count32 == len) {
            for (; i >= 0; i--, pval++)
                *pval = js_dup(arrp[i]);
        } else {
            // Query order is observable; test262 expects descending order.
            for (; i >= 0; i--, pval++) {
                if (-1 == JS_TryGetPropertyInt64(ctx, obj, i, pval))
                    goto exception;
            }
        }
    }

    ret = arr;
    arr = JS_UNDEFINED;

exception:
    JS_FreeValue(ctx, arr);
    JS_FreeValue(ctx, obj);
    return ret;
}

static JSValue js_array_slice(JSContext *ctx, JSValueConst this_val,
                              int argc, JSValueConst *argv, int splice)
{
    JSValue obj, arr, val, len_val;
    int64_t len, start, k, final, n, count, del_count, new_len;
    int kPresent;
    JSValue *arrp;
    uint32_t count32, i, item_count;

    arr = JS_UNDEFINED;
    obj = JS_ToObject(ctx, this_val);
    if (js_get_length64(ctx, &len, obj))
        goto exception;

    if (JS_ToInt64Clamp(ctx, &start, argv[0], 0, len, len))
        goto exception;

    if (splice) {
        if (argc == 0) {
            item_count = 0;
            del_count = 0;
        } else if (argc == 1) {
            item_count = 0;
            del_count = len - start;
        } else {
            item_count = argc - 2;
            if (JS_ToInt64Clamp(ctx, &del_count, argv[1], 0, len - start, 0))
                goto exception;
        }
        if (len + item_count - del_count > MAX_SAFE_INTEGER) {
            JS_ThrowTypeError(ctx, "Array loo long");
            goto exception;
        }
        count = del_count;
    } else {
        item_count = 0; /* avoid warning */
        final = len;
        if (!JS_IsUndefined(argv[1])) {
            if (JS_ToInt64Clamp(ctx, &final, argv[1], 0, len, len))
                goto exception;
        }
        count = max_int64(final - start, 0);
    }
    len_val = js_int64(count);
    arr = JS_ArraySpeciesCreate(ctx, obj, len_val);
    JS_FreeValue(ctx, len_val);
    if (JS_IsException(arr))
        goto exception;

    k = start;
    final = start + count;
    n = 0;
    /* The fast array test on arr ensures that
       JS_CreateDataPropertyUint32() won't modify obj in case arr is
       an exotic object */
    /* Special case fast arrays */
    if (js_get_fast_array(ctx, obj, &arrp, &count32) &&
        js_is_fast_array(ctx, arr)) {
        /* XXX: should share code with fast array constructor */
        for (; k < final && k < count32; k++, n++) {
            if (JS_CreateDataPropertyUint32Const(ctx, arr, n, arrp[k], JS_PROP_THROW) < 0)
                goto exception;
        }
    }
    /* Copy the remaining elements if any (handle case of inherited properties) */
    for (; k < final; k++, n++) {
        kPresent = JS_TryGetPropertyInt64(ctx, obj, k, &val);
        if (kPresent < 0)
            goto exception;
        if (kPresent) {
            if (JS_CreateDataPropertyUint32(ctx, arr, n, val, JS_PROP_THROW) < 0)
                goto exception;
        }
    }
    if (JS_SetProperty(ctx, arr, JS_ATOM_length, js_int64(n)) < 0)
        goto exception;

    if (splice) {
        new_len = len + item_count - del_count;
        if (item_count != del_count) {
            if (JS_CopySubArray(ctx, obj, start + item_count,
                                start + del_count, len - (start + del_count),
                                item_count <= del_count ? +1 : -1) < 0)
                goto exception;

            for (k = len; k-- > new_len; ) {
                if (JS_DeletePropertyInt64(ctx, obj, k, JS_PROP_THROW) < 0)
                    goto exception;
            }
        }
        for (i = 0; i < item_count; i++) {
            if (JS_SetPropertyInt64(ctx, obj, start + i, js_dup(argv[i + 2])) < 0)
                goto exception;
        }
        if (JS_SetProperty(ctx, obj, JS_ATOM_length, js_int64(new_len)) < 0)
            goto exception;
    }
    JS_FreeValue(ctx, obj);
    return arr;

 exception:
    JS_FreeValue(ctx, obj);
    JS_FreeValue(ctx, arr);
    return JS_EXCEPTION;
}

static JSValue js_array_toSpliced(JSContext *ctx, JSValueConst this_val,
                                  int argc, JSValueConst *argv)
{
    JSValue arr, obj, ret, *arrp, *pval, *last;
    JSObject *p;
    int64_t i, j, len, newlen, start, add, del;
    uint32_t count32;

    ret = JS_EXCEPTION;
    arr = JS_UNDEFINED;

    obj = JS_ToObject(ctx, this_val);
    if (js_get_length64(ctx, &len, obj))
        goto exception;

    start = 0;
    if (argc > 0)
        if (JS_ToInt64Clamp(ctx, &start, argv[0], 0, len, len))
            goto exception;

    del = 0;
    if (argc > 0)
        del = len - start;
    if (argc > 1)
        if (JS_ToInt64Clamp(ctx, &del, argv[1], 0, del, 0))
            goto exception;

    add = 0;
    if (argc > 2)
        add = argc - 2;

    newlen = len + add - del;
    if (newlen > MAX_SAFE_INTEGER) {
        JS_ThrowTypeError(ctx, "invalid array length");
        goto exception;
    }

    arr = js_allocate_fast_array(ctx, newlen);
    if (JS_IsException(arr))
        goto exception;

    if (newlen <= 0)
        goto done;

    p = JS_VALUE_GET_OBJ(arr);
    pval = &p->u.array.u.values[0];
    last = &p->u.array.u.values[newlen];

    if (js_get_fast_array(ctx, obj, &arrp, &count32) && count32 == len) {
        for (i = 0; i < start; i++, pval++)
            *pval = js_dup(arrp[i]);
        for (j = 0; j < add; j++, pval++)
            *pval = js_dup(argv[2 + j]);
        for (i += del; i < len; i++, pval++)
            *pval = js_dup(arrp[i]);
    } else {
        for (i = 0; i < start; i++, pval++)
            if (-1 == JS_TryGetPropertyInt64(ctx, obj, i, pval))
                goto exception;
        for (j = 0; j < add; j++, pval++)
            *pval = js_dup(argv[2 + j]);
        for (i += del; i < len; i++, pval++)
            if (-1 == JS_TryGetPropertyInt64(ctx, obj, i, pval))
                goto exception;
    }

    assert(pval == last);

done:
    ret = arr;
    arr = JS_UNDEFINED;

exception:
    JS_FreeValue(ctx, arr);
    JS_FreeValue(ctx, obj);
    return ret;
}

static JSValue js_array_copyWithin(JSContext *ctx, JSValueConst this_val,
                                   int argc, JSValueConst *argv)
{
    JSValue obj;
    int64_t len, from, to, final, count;

    obj = JS_ToObject(ctx, this_val);
    if (js_get_length64(ctx, &len, obj))
        goto exception;

    if (JS_ToInt64Clamp(ctx, &to, argv[0], 0, len, len))
        goto exception;

    if (JS_ToInt64Clamp(ctx, &from, argv[1], 0, len, len))
        goto exception;

    final = len;
    if (argc > 2 && !JS_IsUndefined(argv[2])) {
        if (JS_ToInt64Clamp(ctx, &final, argv[2], 0, len, len))
            goto exception;
    }

    count = min_int64(final - from, len - to);

    if (JS_CopySubArray(ctx, obj, to, from, count,
                        (from < to && to < from + count) ? -1 : +1))
        goto exception;

    return obj;

 exception:
    JS_FreeValue(ctx, obj);
    return JS_EXCEPTION;
}

static int64_t JS_FlattenIntoArray(JSContext *ctx, JSValueConst target,
                                   JSValueConst source, int64_t sourceLen,
                                   int64_t targetIndex, int depth,
                                   JSValueConst mapperFunction,
                                   JSValueConst thisArg)
{
    JSValue element;
    int64_t sourceIndex, elementLen;
    int present, is_array;

    if (js_check_stack_overflow(ctx->rt, 0)) {
        JS_ThrowStackOverflow(ctx);
        return -1;
    }

    for (sourceIndex = 0; sourceIndex < sourceLen; sourceIndex++) {
        present = JS_TryGetPropertyInt64(ctx, source, sourceIndex, &element);
        if (present < 0)
            return -1;
        if (!present)
            continue;
        if (!JS_IsUndefined(mapperFunction)) {
            JSValue index = js_int64(sourceIndex);
            JSValueConst args[3] = { element, index, source };
            JSValue ret = JS_Call(ctx, mapperFunction, thisArg, 3, args);
            JS_FreeValue(ctx, element);
            JS_FreeValue(ctx, index);
            if (JS_IsException(ret))
                return -1;
            element = ret;
        }
        if (depth > 0) {
            is_array = js_is_array(ctx, element);
            if (is_array < 0)
                goto fail;
            if (is_array) {
                if (js_get_length64(ctx, &elementLen, element) < 0)
                    goto fail;
                targetIndex = JS_FlattenIntoArray(ctx, target, element,
                                                  elementLen, targetIndex,
                                                  depth - 1,
                                                  JS_UNDEFINED, JS_UNDEFINED);
                if (targetIndex < 0)
                    goto fail;
                JS_FreeValue(ctx, element);
                continue;
            }
        }
        if (targetIndex >= MAX_SAFE_INTEGER) {
            JS_ThrowTypeError(ctx, "Array too long");
            goto fail;
        }
        if (JS_DefinePropertyValueInt64(ctx, target, targetIndex, element,
                                        JS_PROP_C_W_E | JS_PROP_THROW) < 0)
            return -1;
        targetIndex++;
    }
    return targetIndex;

fail:
    JS_FreeValue(ctx, element);
    return -1;
}

static JSValue js_array_flatten(JSContext *ctx, JSValueConst this_val,
                                int argc, JSValueConst *argv, int map)
{
    JSValue obj, arr;
    JSValueConst mapperFunction, thisArg;
    int64_t sourceLen;
    int depthNum;

    arr = JS_UNDEFINED;
    obj = JS_ToObject(ctx, this_val);
    if (js_get_length64(ctx, &sourceLen, obj))
        goto exception;

    depthNum = 1;
    mapperFunction = JS_UNDEFINED;
    thisArg = JS_UNDEFINED;
    if (map) {
        mapperFunction = argv[0];
        if (argc > 1) {
            thisArg = argv[1];
        }
        if (check_function(ctx, mapperFunction))
            goto exception;
    } else {
        if (argc > 0 && !JS_IsUndefined(argv[0])) {
            if (JS_ToInt32Sat(ctx, &depthNum, argv[0]) < 0)
                goto exception;
        }
    }
    arr = JS_ArraySpeciesCreate(ctx, obj, js_int32(0));
    if (JS_IsException(arr))
        goto exception;
    if (JS_FlattenIntoArray(ctx, arr, obj, sourceLen, 0, depthNum,
                            mapperFunction, thisArg) < 0)
        goto exception;
    JS_FreeValue(ctx, obj);
    return arr;

exception:
    JS_FreeValue(ctx, obj);
    JS_FreeValue(ctx, arr);
    return JS_EXCEPTION;
}

/* Array sort */

typedef struct ValueSlot {
    JSValue val;
    JSString *str;
    int64_t pos;
} ValueSlot;

struct array_sort_context {
    JSContext *ctx;
    int exception;
    int has_method;
    JSValueConst method;
};

static int js_array_cmp_generic(const void *a, const void *b, void *opaque) {
    struct array_sort_context *psc = opaque;
    JSContext *ctx = psc->ctx;
    JSValueConst argv[2];
    JSValue res;
    ValueSlot *ap = (ValueSlot *)(void *)a;
    ValueSlot *bp = (ValueSlot *)(void *)b;
    int cmp;

    if (psc->exception)
        return 0;

    if (psc->has_method) {
        /* custom sort function is specified as returning 0 for identical
         * objects: avoid method call overhead.
         */
        if (!memcmp(&ap->val, &bp->val, sizeof(ap->val)))
            goto cmp_same;
        argv[0] = ap->val;
        argv[1] = bp->val;
        res = JS_Call(ctx, psc->method, JS_UNDEFINED, 2, argv);
        if (JS_IsException(res))
            goto exception;
        if (JS_VALUE_GET_TAG(res) == JS_TAG_INT) {
            int val = JS_VALUE_GET_INT(res);
            cmp = (val > 0) - (val < 0);
        } else {
            double val;
            if (JS_ToFloat64Free(ctx, &val, res) < 0)
                goto exception;
            cmp = (val > 0) - (val < 0);
        }
    } else {
        /* Not supposed to bypass ToString even for identical objects as
         * tested in test262/test/built-ins/Array/prototype/sort/bug_596_1.js
         */
        if (!ap->str) {
            JSValue str = JS_ToString(ctx, ap->val);
            if (JS_IsException(str))
                goto exception;
            ap->str = JS_VALUE_GET_STRING(str);
        }
        if (!bp->str) {
            JSValue str = JS_ToString(ctx, bp->val);
            if (JS_IsException(str))
                goto exception;
            bp->str = JS_VALUE_GET_STRING(str);
        }
        cmp = js_string_compare(ap->str, bp->str);
    }
    if (cmp != 0)
        return cmp;
cmp_same:
    /* make sort stable: compare array offsets */
    return (ap->pos > bp->pos) - (ap->pos < bp->pos);

exception:
    psc->exception = 1;
    return 0;
}

/* read the present, non-undefined elements into s->array (undefined -> the end, holes -> after that), alloc tmp,
   set up the first merge block. Returns 0 ok / -1 exception (safe to js_array_sort_end). */
/* The receiver half. `method` is hdr.argv[0] — owned by the header for the machine's whole life, which is why
   the state can borrow it. */
static int js_array_sort_recv(JSContext *ctx, JSArraySort *s)
{
    int64_t i;
    s->obj = JS_UNDEFINED; s->method = step_arg(&s->hdr, 0); s->array = NULL; s->tmp = NULL;
    s->n = 0; s->len = 0; s->undefined_count = 0; s->pending = 0;
    s->width = 1; s->i = 0; s->lo = s->mid = s->hi = s->l = s->r = s->k = 0;
    for (i = 0; i < 4; i++) s->cb_args[i] = JS_UNDEFINED;
    s->obj = JS_ToObject(ctx, s->hdr.this_val);
    if (JS_IsException(s->obj)) { s->obj = JS_UNDEFINED; return -1; }
    return 0;
}

/* Collect the present, non-undefined elements into the merge array. Runs after the length, so it is its own
   function rather than the tail of an init. */
static int js_array_sort_collect(JSContext *ctx, JSArraySort *s)
{
    int64_t i, pos = 0; int present;
    if (s->len > 0) {
        s->array = js_malloc(ctx, (size_t)s->len * sizeof(ValueSlot));
        if (!s->array) return -1;
    }
    for (i = 0; i < s->len; i++) {
        JSValue v;
        present = JS_TryGetPropertyInt64(ctx, s->obj, i, &v);
        if (present < 0) { s->n = pos; return -1; }
        if (present == 0) continue;
        if (JS_IsUndefined(v)) { s->undefined_count++; continue; }
        s->array[pos].val = v; s->array[pos].str = NULL; s->array[pos].pos = i; pos++;
    }
    s->n = pos;
    if (s->n > 1) {
        s->tmp = js_malloc(ctx, (size_t)s->n * sizeof(ValueSlot));
        if (!s->tmp) return -1;
        s->lo = 0; s->mid = 1 < s->n ? 1 : s->n; s->hi = 2 < s->n ? 2 : s->n;   /* first block, width=1 */
        s->l = 0; s->r = s->mid; s->k = 0;
    }
    return 0;
}

/* Drive the merge until the next comparison is needed (return 1, out_args = the two element values) or the sort
   is complete (return 0). `res` (owned) is the comparator's return value for the pending comparison, or JS_UNDEFINED
   on the first call. Returns -1 on exception. */
static int js_array_sort_step(JSContext *ctx, JSArraySort *s, JSValue res, JSValueConst out_args[2])
{
    if (s->pending) {
        double v;
        if (JS_ToFloat64Free(ctx, &v, res) < 0) return -1;   /* consumes res */
        s->pending = 0;
        if (v <= 0) s->tmp[s->k++] = s->array[s->l++];   /* stable: <= keeps the left (earlier) element first */
        else        s->tmp[s->k++] = s->array[s->r++];
    } else {
        JS_FreeValue(ctx, res);   /* JS_UNDEFINED on the first call, or a stray value */
    }
    for (;;) {
        if (s->width >= s->n) break;                 /* fully sorted (n<=1 lands here immediately) */
        if (s->i >= s->n) {                          /* this width pass done -> next width */
            s->width *= 2; s->i = 0;
            if (s->width >= s->n) break;
            s->lo = 0; s->mid = s->width < s->n ? s->width : s->n;
            s->hi = 2 * s->width < s->n ? 2 * s->width : s->n;
            s->l = 0; s->r = s->mid; s->k = 0;
            continue;
        }
        /* merge invariants — an active block [lo,hi) with ordered cursors, and the exactly-conserved output
           count (each element placed into tmp is consumed from exactly one run). A violation is a state-machine
           bug; crash at its origin (offensive programming) rather than silently mis-sorting. */
        assert(s->lo <= s->l && s->l <= s->mid && s->mid <= s->r && s->r <= s->hi && s->hi <= s->n);
        assert(s->k - s->lo == (s->l - s->lo) + (s->r - s->mid));
        if (s->l < s->mid && s->r < s->hi) {
            if (JS_IsUndefined(s->method)) {
                /* DEFAULT ordering: ToString both and compare — no callback, so no suspension point. It lives HERE
                   so ONE machine covers both comparator kinds; leaving it in a second C body is the seam every bug
                   this session came from. ToString is not bypassed for identical values (test262
                   Array/prototype/sort/bug_596_1.js), and ties fall back to original position for stability. */
                ValueSlot *ap = &s->array[s->l], *bp = &s->array[s->r];
                int cmp;
                if (!ap->str) {
                    JSValue str = JS_ToString(ctx, ap->val);
                    if (JS_IsException(str)) return -1;
                    ap->str = JS_VALUE_GET_STRING(str);
                }
                if (!bp->str) {
                    JSValue str = JS_ToString(ctx, bp->val);
                    if (JS_IsException(str)) return -1;
                    bp->str = JS_VALUE_GET_STRING(str);
                }
                cmp = js_string_compare(ap->str, bp->str);
                if (cmp == 0)
                    cmp = (ap->pos > bp->pos) - (ap->pos < bp->pos);
                if (cmp <= 0) s->tmp[s->k++] = s->array[s->l++];
                else          s->tmp[s->k++] = s->array[s->r++];
                continue;
            }
            out_args[0] = s->array[s->l].val;   /* the ONE suspension point (a comparator was supplied) */
            out_args[1] = s->array[s->r].val;
            s->pending = 1;
            return 1;
        }
        while (s->l < s->mid) s->tmp[s->k++] = s->array[s->l++];   /* drain remainders */
        while (s->r < s->hi)  s->tmp[s->k++] = s->array[s->r++];
        { int64_t t; for (t = s->lo; t < s->hi; t++) s->array[t] = s->tmp[t]; }   /* copy block back */
        s->i += 2 * s->width;                        /* next block at this width */
        if (s->i < s->n) {
            s->lo = s->i; s->mid = s->i + s->width < s->n ? s->i + s->width : s->n;
            s->hi = s->i + 2 * s->width < s->n ? s->i + 2 * s->width : s->n;
            s->l = s->lo; s->r = s->mid; s->k = s->lo;
        }
    }
    return 0;   /* caller writes the sorted array back in js_array_sort_end */
}

/* On ok: write the sorted elements back to obj, then the undefineds, then delete the holes; return obj (owned,
   transferred to caller). On failure: free everything, return JS_EXCEPTION. Either way the state is released. */
static JSValue js_array_sort_end(JSContext *ctx, JSArraySort *s, bool ok)
{
    int64_t i, w = 0;
    if (!ok) goto fail;
    while (w < s->n) {                               /* sorted present elements back in place */
        /* the default-ordering path caches each element's ToString in .str; release it here, exactly as the
           rqsort writeback did. Nothing populated .str while only comparator sorts reached this machine, which
           is why its absence was invisible until the default path was folded in. */
        if (s->array[w].str) { JS_FreeValue(ctx, JS_MKPTR(JS_TAG_STRING, s->array[w].str)); s->array[w].str = NULL; }
        if (s->array[w].pos == w) { JS_FreeValue(ctx, s->array[w].val); }
        else if (JS_SetPropertyInt64(ctx, s->obj, w, s->array[w].val) < 0) { w++; goto fail; }
        w++;
    }
    js_free(ctx, s->array); s->array = NULL;
    js_free(ctx, s->tmp); s->tmp = NULL;
    for (i = w; s->undefined_count-- > 0; i++)
        if (JS_SetPropertyInt64(ctx, s->obj, i, JS_UNDEFINED) < 0) goto fail2;
    for (; i < s->len; i++)
        if (JS_DeletePropertyInt64(ctx, s->obj, i, JS_PROP_THROW) < 0) goto fail2;
    return s->obj;
fail:
    for (; w < s->n; w++) {
        if (s->array[w].str) JS_FreeValue(ctx, JS_MKPTR(JS_TAG_STRING, s->array[w].str));
        JS_FreeValue(ctx, s->array[w].val);
    }
    js_free(ctx, s->array); s->array = NULL;
    js_free(ctx, s->tmp); s->tmp = NULL;
fail2:
    JS_FreeValue(ctx, s->obj); s->obj = JS_UNDEFINED;
    return JS_EXCEPTION;
}

/* The sort recognizer is DELETED. Its comment used to say a default sort or a native comparator "stays on rqsort"
   — that sentence WAS the dual system: it named the second implementation the recognizer existed to select. With
   rqsort's body gone and the default ordering folded into js_array_sort_step, there is nothing to select. */

/* DELETED: the rqsort-based js_array_sort. It was a SECOND full implementation of sort — its own collection loop
   with slack growth, its own undefined/hole ordering, its own writeback — duplicating js_array_sort_init /
   _step / _end, which the trampoline already drives. Sort is now that one machine (STEPDEF_ARRAY_SORT), and with
   the default-comparison branch in js_array_sort_step there is no case left for a C body to serve. */
/* sort and toSorted are ONE machine: same comparator drive, same merge, same writeback. The only difference is
   WHAT is sorted — the receiver, or a dense copy of it — so it is the prologue that branches on hdr.arg, not a
   second machine. (toSorted does not use Array[@@species]; it always yields a base Array.) The prologue is in
   three stages because LengthOfArrayLike sits in the middle of it and its ToLength can run user code. */
static int js_array_sort_copy(JSContext *ctx, JSArraySort *s)
{
    JSValue arr, *arrp, *pval;
    JSObject *p;
    int64_t i, len = s->len;
    uint32_t count32;

    /* toSorted: a.slice().sort(), except that a.slice() leaves holes in a sparse array intact whereas
       a.toSorted() replaces them with undefined — so the copy is built dense here. */
    arr = js_allocate_fast_array(ctx, len);
    if (JS_IsException(arr))
        return -1;
    if (len > 0) {
        p = JS_VALUE_GET_OBJ(arr);
        i = 0;
        pval = p->u.array.u.values;
        if (js_get_fast_array(ctx, s->obj, &arrp, &count32) && count32 == len) {
            for (; i < len; i++, pval++)
                *pval = js_dup(arrp[i]);
        } else {
            for (; i < len; i++, pval++) {
                if (-1 == JS_TryGetPropertyInt64(ctx, s->obj, i, pval)) {
                    p->u.array.count = i;   /* only the slots written so far are initialised */
                    JS_FreeValue(ctx, arr);
                    return -1;
                }
            }
        }
        p->u.array.count = len;
    }
    JS_FreeValue(ctx, s->obj);
    s->obj = arr;   /* the sort, the writeback and the result are all the copy from here on */
    return 0;
}

static int js_array_sort_vstep(JSContext *ctx, void *st, JSValue cb_result, JSValue **out_cb, int *out_argc)
{
    JSArraySort *s = st;
    int r;
    if (s->hdr.stage == 0) {
        JSValueConst method = step_arg(&s->hdr, 0);
        JS_FreeValue(ctx, cb_result);
        cb_result = JS_UNDEFINED;
        if (!JS_IsUndefined(method) && check_function(ctx, method))
            return -1;   /* spec: a non-callable comparator throws BEFORE anything is read */
        if (js_array_sort_recv(ctx, s))
            return -1;
        s->hdr.stage = 1;
    }
    if (s->hdr.stage == 1) {   /* LengthOfArrayLike, re-entered until it finishes */
        r = step_length_run(ctx, &s->hdr, s->obj, cb_result, &s->len, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->hdr.stage = 2;
    }
    if (s->hdr.stage == 2) {
        s->hdr.stage = 3;
        if (s->hdr.arg && js_array_sort_copy(ctx, s)) return -1;
        if (js_array_sort_collect(ctx, s)) return -1;
    }
    r = js_array_sort_step(ctx, s, cb_result, (JSValueConst *)&s->cb_args[2]);   /* consumes cb_result */
    if (r < 0) return -1;
    if (r == 0) return 0;
    s->cb_args[0] = JS_UNDEFINED;            /* the comparator gets this = undefined */
    s->cb_args[1] = s->method;
    *out_cb = s->cb_args; *out_argc = 2;
    return 3;
}

static JSValue js_array_sort_vfini(JSContext *ctx, void *st, bool take_result)
{
    JSArraySort *s = st;
    JSValue r = js_array_sort_end(ctx, s, take_result);   /* writes back and yields the array */
    js_free(ctx, s);
    if (!take_result) { JS_FreeValue(ctx, r); return JS_UNDEFINED; }
    return r;
}

typedef struct JSArrayIteratorData {
    JSValue obj;
    JSIteratorKindEnum kind;
    uint32_t idx;
} JSArrayIteratorData;

static void js_array_iterator_finalizer(JSRuntime *rt, JSValueConst val)
{
    JSObject *p = JS_VALUE_GET_OBJ(val);
    JSArrayIteratorData *it = p->u.array_iterator_data;
    if (it) {
        JS_FreeValueRT(rt, it->obj);
        js_free_rt(rt, it);
    }
}

static void js_array_iterator_mark(JSRuntime *rt, JSValueConst val,
                                   JS_MarkFunc *mark_func)
{
    JSObject *p = JS_VALUE_GET_OBJ(val);
    JSArrayIteratorData *it = p->u.array_iterator_data;
    if (it) {
        JS_MarkValue(rt, it->obj, mark_func);
    }
}

static JSValue js_create_array(JSContext *ctx, int len, JSValueConst *tab)
{
    JSValue obj;
    JSObject *p;
    int i;

    obj = JS_NewArray(ctx);
    if (JS_IsException(obj))
        return JS_EXCEPTION;
    if (len > 0) {
        p = JS_VALUE_GET_OBJ(obj);
        if (expand_fast_array(ctx, p, len) < 0) {
            JS_FreeValue(ctx, obj);
            return JS_EXCEPTION;
        }
        p->u.array.count = len;
        for(i = 0; i < len; i++)
            p->u.array.u.values[i] = js_dup(tab[i]);
        /* update the 'length' field */
        set_value(ctx, &p->prop[0].u.value, js_int32(len));
    }
    return obj;
}

static JSValue js_create_array_iterator(JSContext *ctx, JSValueConst this_val,
                                        int argc, JSValueConst *argv, int magic)
{
    JSValue enum_obj, arr;
    JSArrayIteratorData *it;
    JSIteratorKindEnum kind;
    int class_id;

    kind = magic & 3;
    if (magic & 4) {
        /* string iterator case */
        arr = JS_ToStringCheckObject(ctx, this_val);
        class_id = JS_CLASS_STRING_ITERATOR;
    } else {
        arr = JS_ToObject(ctx, this_val);
        class_id = JS_CLASS_ARRAY_ITERATOR;
    }
    if (JS_IsException(arr))
        goto fail;
    enum_obj = JS_NewObjectClass(ctx, class_id);
    if (JS_IsException(enum_obj))
        goto fail;
    it = js_malloc(ctx, sizeof(*it));
    if (!it)
        goto fail1;
    it->obj = arr;
    it->kind = kind;
    it->idx = 0;
    JS_SetOpaqueInternal(enum_obj, it);
    return enum_obj;
 fail1:
    JS_FreeValue(ctx, enum_obj);
 fail:
    JS_FreeValue(ctx, arr);
    return JS_EXCEPTION;
}

static JSValue js_array_iterator_next(JSContext *ctx, JSValueConst this_val,
                                      int argc, JSValueConst *argv,
                                      int *pdone, int magic)
{
    JSArrayIteratorData *it;
    uint32_t len, idx;
    JSValue val, obj;
    JSObject *p;

    it = JS_GetOpaque2(ctx, this_val, JS_CLASS_ARRAY_ITERATOR);
    if (!it)
        goto fail1;
    if (JS_IsUndefined(it->obj))
        goto done;
    p = JS_VALUE_GET_OBJ(it->obj);
    if (is_typed_array(p->class_id)) {
        if (typed_array_is_oob(p)) {
            JS_ThrowTypeErrorArrayBufferOOB(ctx);
            goto fail1;
        }
        len = p->u.array.count;
    } else {
        if (js_get_length32(ctx, &len, it->obj)) {
        fail1:
            *pdone = false;
            return JS_EXCEPTION;
        }
    }
    idx = it->idx;
    if (idx >= len) {
        JS_FreeValue(ctx, it->obj);
        it->obj = JS_UNDEFINED;
    done:
        *pdone = true;
        return JS_UNDEFINED;
    }
    it->idx = idx + 1;
    *pdone = false;
    if (it->kind == JS_ITERATOR_KIND_KEY) {
        return js_uint32(idx);
    } else {
        val = JS_GetPropertyUint32(ctx, it->obj, idx);
        if (JS_IsException(val))
            return JS_EXCEPTION;
        if (it->kind == JS_ITERATOR_KIND_VALUE) {
            return val;
        } else {
            JSValueConst args[2];
            JSValue num;
            num = js_uint32(idx);
            args[0] = num;
            args[1] = val;
            obj = js_create_array(ctx, 2, args);
            JS_FreeValue(ctx, val);
            JS_FreeValue(ctx, num);
            return obj;
        }
    }
}


static void js_iterator_wrap_finalizer(JSRuntime *rt, JSValueConst val)
{
    JSObject *p = JS_VALUE_GET_OBJ(val);
    JSIteratorWrapData *it = p->u.iterator_wrap_data;
    if (it) {
        JS_FreeValueRT(rt, it->wrapped_iter);
        JS_FreeValueRT(rt, it->wrapped_next);
        js_free_rt(rt, it);
    }
}

static void js_iterator_wrap_mark(JSRuntime *rt, JSValueConst val,
                                  JS_MarkFunc *mark_func)
{
    JSObject *p = JS_VALUE_GET_OBJ(val);
    JSIteratorWrapData *it = p->u.iterator_wrap_data;
    if (it) {
        JS_MarkValue(rt, it->wrapped_iter, mark_func);
        JS_MarkValue(rt, it->wrapped_next, mark_func);
    }
}

static JSValue js_iterator_wrap_next(JSContext *ctx, JSValueConst this_val,
                                     int argc, JSValueConst *argv,
                                     int *pdone, int magic)
{
    JSIteratorWrapData *it;
    JSValue method, ret;
    it = JS_GetOpaque2(ctx, this_val, JS_CLASS_ITERATOR_WRAP);
    if (!it)
        return JS_EXCEPTION;
    if (magic == GEN_MAGIC_NEXT)
        return JS_IteratorNext(ctx, it->wrapped_iter, it->wrapped_next, argc, argv, pdone);
    method = JS_GetProperty(ctx, it->wrapped_iter, JS_ATOM_return);
    if (JS_IsException(method))
        return JS_EXCEPTION;
    if (JS_IsNull(method) || JS_IsUndefined(method)) {
        *pdone = true;
        return JS_UNDEFINED;
    }
    ret = JS_IteratorNext2(ctx, it->wrapped_iter, method, argc, argv, pdone);
    JS_FreeValue(ctx, method);
    return ret;
}

static const JSCFunctionListEntry js_iterator_wrap_proto_funcs[] = {
    JS_ITERATOR_NEXT_DEF("next", 0, js_iterator_wrap_next, GEN_MAGIC_NEXT ),
    JS_ITERATOR_NEXT_DEF("return", 0, js_iterator_wrap_next, GEN_MAGIC_RETURN ),
};

static int check_iterator(JSContext *ctx, JSValueConst obj);

static JSValue js_iterator_constructor_getset(JSContext *ctx,
                                              JSValueConst this_val,
                                              int argc, JSValueConst *argv,
                                              int magic,
                                              JSValueConst *func_data)
{
    int ret;

    if (magic) { // setter (the getter is registered with magic == 0)
        // SetterThatIgnoresPrototypeProperties(%Iterator.prototype%, "constructor", v)
        // argv[0] is the assigned value; it defaults to undefined because the
        // setter is registered with length 1 (see JS_AddIntrinsicBaseObjects).
        if (check_iterator(ctx, this_val) < 0)
            return JS_EXCEPTION;
        if (js_same_value(ctx, this_val, ctx->class_proto[JS_CLASS_ITERATOR]))
            return JS_ThrowTypeError(ctx, "Cannot assign to read only property");
        ret = JS_GetOwnProperty(ctx, NULL, this_val, JS_ATOM_constructor);
        if (ret < 0)
            return JS_EXCEPTION;
        if (ret) {
            if (JS_SetProperty(ctx, this_val, JS_ATOM_constructor, js_dup(argv[0])) < 0)
                return JS_EXCEPTION;
        } else {
            if (JS_DefinePropertyValue(ctx, this_val, JS_ATOM_constructor,
                                       js_dup(argv[0]),
                                       JS_PROP_C_W_E | JS_PROP_THROW) < 0)
                return JS_EXCEPTION;
        }
        return JS_UNDEFINED;
    }
    return js_dup(func_data[0]);
}

static JSValue js_iterator_constructor(JSContext *ctx, JSValueConst new_target,
                                       int argc, JSValueConst *argv)
{
    JSObject *p;

    if (JS_TAG_OBJECT != JS_VALUE_GET_TAG(new_target))
        return JS_ThrowTypeError(ctx, "constructor requires 'new'");
    p = JS_VALUE_GET_OBJ(new_target);
    if (p->class_id == JS_CLASS_C_FUNCTION)
        if (p->u.cfunc.c_function.generic == js_iterator_constructor)
            return JS_ThrowTypeError(ctx, "abstract class not constructable");
    return js_create_from_ctor(ctx, new_target, JS_CLASS_ITERATOR);
}

typedef struct JSIteratorConcatData {
    uint32_t index : 31; // elements (not pairs!) in values[] array
    uint32_t unused : 1;
    uint32_t count : 31;
    uint32_t running : 1;
    JSValue iter, next, values[]; // array of (object, method) pairs
} JSIteratorConcatData;

static void js_iterator_concat_finalizer(JSRuntime *rt, JSValueConst val)
{
    JSObject *p = JS_VALUE_GET_OBJ(val);
    JSIteratorConcatData *it = p->u.iterator_concat_data;
    if (it) {
        JS_FreeValueRT(rt, it->iter);
        JS_FreeValueRT(rt, it->next);
        for (uint32_t i = it->index; i < it->count; i++)
            JS_FreeValueRT(rt, it->values[i]);
        js_free_rt(rt, it);
    }
}

static void js_iterator_concat_mark(JSRuntime *rt, JSValueConst val,
                                    JS_MarkFunc *mark_func)
{
    JSObject *p = JS_VALUE_GET_OBJ(val);
    JSIteratorConcatData *it = p->u.iterator_concat_data;
    if (it) {
        JS_MarkValue(rt, it->iter, mark_func);
        JS_MarkValue(rt, it->next, mark_func);
        for (uint32_t i = it->index; i < it->count; i++)
            JS_MarkValue(rt, it->values[i], mark_func);
    }
}

static JSValue js_iterator_concat_next(JSContext *ctx, JSValueConst this_val,
                                       int argc, JSValueConst *argv,
                                       int *pdone, int magic)
{
    JSValue iter, item, next, val, *obj, *meth;
    JSIteratorConcatData *it;
    int done;

    it = JS_GetOpaque2(ctx, this_val, JS_CLASS_ITERATOR_CONCAT);
    if (!it)
        return JS_EXCEPTION;
    if (it->running)
        return JS_ThrowTypeError(ctx, "already running");
    it->running = true;
next:
    if (it->index >= it->count) {
        *pdone = true;
        val = JS_UNDEFINED;
        goto done;
    }
    obj = &it->values[it->index + 0];
    meth = &it->values[it->index + 1];
    iter = it->iter;
    if (JS_IsUndefined(iter)) {
        iter = JS_GetIterator2(ctx, *obj, *meth);
        if (JS_IsException(iter))
            goto fail;
        it->iter = iter;
    }
    next = it->next;
    if (JS_IsUndefined(next)) {
        next = JS_GetProperty(ctx, iter, JS_ATOM_next);
        if (JS_IsException(next))
            goto fail;
        it->next = next;
    }
    item = JS_IteratorNext2(ctx, iter, next, 0, NULL, &done);
    if (JS_IsException(item))
        goto fail;
    if (!done) {
        *pdone = false;
        val = item;
        goto done;
    }
    // done==1 means really done, done==2 means "unknown, inspect object"
    if (done == 2) {
        val = JS_GetProperty(ctx, item, JS_ATOM_done);
        if (JS_IsException(val)) {
            JS_FreeValue(ctx, item);
            goto fail;
        }
        done = JS_ToBoolFree(ctx, val);
    }
    if (done) {
        JS_FreeValue(ctx, item);
        JS_FreeValue(ctx, iter);
        JS_FreeValue(ctx, next);
        it->iter = JS_UNDEFINED;
        it->next = JS_UNDEFINED;
        JS_FreeValue(ctx, *meth);
        JS_FreeValue(ctx, *obj);
        it->index += 2;
        goto next;
    }
    val = JS_GetProperty(ctx, item, JS_ATOM_value);
    JS_FreeValue(ctx, item);
    *pdone = false;
done:
    it->running = false;
    return val;
fail:
    val = JS_EXCEPTION;
    goto done;
}

static JSValue js_iterator_concat_return(JSContext *ctx, JSValueConst this_val,
                                         int argc, JSValueConst *argv)
{
    JSIteratorConcatData *it;
    JSValue ret, *pval;

    it = JS_GetOpaque2(ctx, this_val, JS_CLASS_ITERATOR_CONCAT);
    if (!it)
        return JS_EXCEPTION;
    if (it->running)
        return JS_ThrowTypeError(ctx, "already running");
    ret = JS_UNDEFINED;
    if (!JS_IsUndefined(it->iter)) {
        ret = JS_GetProperty(ctx, it->iter, JS_ATOM_return);
        if (JS_IsException(ret))
            return JS_EXCEPTION;
        it->running = true;
        ret = JS_CallFree(ctx, ret, it->iter, 0, NULL);
        it->running = false;
    }
    while (it->index < it->count) {
        pval = &it->values[it->index++];
        JS_FreeValue(ctx, *pval);
        *pval = JS_UNDEFINED;
    }
    JS_FreeValue(ctx, it->iter);
    JS_FreeValue(ctx, it->next);
    it->iter = JS_UNDEFINED;
    it->next = JS_UNDEFINED;
    return ret;
}

static const JSCFunctionListEntry js_iterator_concat_proto_funcs[] = {
    JS_ITERATOR_NEXT_DEF("next", 1, js_iterator_concat_next, 0 ),
    JS_CFUNC_DEF("return", 1, js_iterator_concat_return ),
    JS_PROP_STRING_DEF("[Symbol.toStringTag]", "Iterator Concat", JS_PROP_CONFIGURABLE ),
};

static JSValue js_iterator_concat(JSContext *ctx, JSValueConst this_val,
                                  int argc, JSValueConst *argv)
{
    JSIteratorConcatData *it;
    JSValue obj, method;

    it = js_malloc(ctx, sizeof(*it) + 2*argc * sizeof(it->values[0]));
    if (!it)
        return JS_EXCEPTION;
    it->running = false;
    it->index = 0;
    it->count = 0;
    it->iter = JS_UNDEFINED;
    it->next = JS_UNDEFINED;
    for (int i = 0; i < argc; i++) {
        JSValueConst obj = argv[i];
        if (!JS_IsObject(obj)) {
            JS_ThrowTypeErrorNotAnObject(ctx);
            goto fail;
        }
        method = JS_GetProperty(ctx, obj, JS_ATOM_Symbol_iterator);
        if (JS_IsException(method))
            goto fail;
        if (!JS_IsFunction(ctx, method)) {
            JS_ThrowTypeErrorNotAFunction(ctx);
            JS_FreeValue(ctx, method);
            goto fail;
        }
        it->values[it->count++] = js_dup(obj);
        it->values[it->count++] = method;
    }
    obj = JS_NewObjectClass(ctx, JS_CLASS_ITERATOR_CONCAT);
    if (JS_IsException(obj))
        goto fail;
    JS_SetOpaqueInternal(obj, it);
    return obj;
fail:
    for (uint32_t i = 0; i < it->count; i++)
        JS_FreeValue(ctx, it->values[i]);
    js_free(ctx, it);
    return JS_EXCEPTION;
}

static JSValue js_iterator_from(JSContext *ctx, JSValueConst this_val,
                                int argc, JSValueConst *argv)
{
    /* The C body is DELETED, not narrowed. 27.1.3.1 lives on the tramp (do_iterfrom_tramp + the shared acquire's
       flattenable mode + the CONT_ITER_FROM deliver), which is the only implementation: it ACQUIRES by calling
       @@iterator, and calling it from here is off-chain by construction. Reaching this entry means a call SHAPE
       was never routed (`Iterator.from.apply(...)`, an invocation from inside a C builtin) — name that shape
       instead of quietly running a second, non-suspending copy of the algorithm. */
    DFAIL("Iterator.from reached its C entry — route that call shape onto the consume machine "
          "(do_iterfrom_tramp performs the whole of 27.1.3.1)");
    return JS_ThrowTypeError(ctx, "Iterator.from: unrouted call shape (no off-tramp implementation exists)");
}

static int check_iterator(JSContext *ctx, JSValueConst obj)
{
    if (!JS_IsObject(obj)) {
        JS_ThrowTypeErrorNotAnObject(ctx);
        return -1;
    }
    return 0;
}

static JSValue js_async_dispose_to_undef(JSContext *ctx, JSValueConst this_val,
                                         int argc, JSValueConst *argv,
                                         int magic, JSValueConst *func_data);

static JSValue js_iterator_proto_dispose(JSContext *ctx, JSValueConst this_val,
                                         int argc, JSValueConst *argv)
{
    JSValue method;

    method = JS_GetProperty(ctx, this_val, JS_ATOM_return);
    if (JS_IsException(method))
        return JS_EXCEPTION;
    if (JS_IsUndefined(method))
        return JS_UNDEFINED;
    return JS_CallFree(ctx, method, this_val, 0, NULL);
}

static JSValue js_async_iterator_proto_dispose(JSContext *ctx,
                                               JSValueConst this_val,
                                               int argc, JSValueConst *argv)
{
    JSValue method, ret, promise, undef_fn, then_args[1], result;
    JSValue undef = JS_UNDEFINED;

    method = JS_GetProperty(ctx, this_val, JS_ATOM_return);
    if (JS_IsException(method)) {
        JSValue exc = JS_GetException(ctx);
        JSValue p = js_promise_resolve(ctx, ctx->promise_ctor, 1, vc(&exc), 1);
        JS_FreeValue(ctx, exc);
        return p;
    }
    if (JS_IsUndefined(method)) {
        return js_promise_resolve(ctx, ctx->promise_ctor, 1, vc(&undef), 0);
    }
    ret = JS_Call(ctx, method, this_val, 0, NULL);
    JS_FreeValue(ctx, method);
    if (JS_IsException(ret)) {
        JSValue exc = JS_GetException(ctx);
        JSValue p = js_promise_resolve(ctx, ctx->promise_ctor, 1, vc(&exc), 1);
        JS_FreeValue(ctx, exc);
        return p;
    }
    /* Wrap in Promise.resolve(ret).then(() => undefined) */
    promise = js_promise_resolve(ctx, ctx->promise_ctor, 1, vc(&ret), 0);
    JS_FreeValue(ctx, ret);
    if (JS_IsException(promise))
        return promise;
    undef_fn = JS_NewCFunctionData(ctx, js_async_dispose_to_undef, 0, 0, 0,
                                   NULL);
    if (JS_IsException(undef_fn)) {
        JS_FreeValue(ctx, promise);
        return JS_EXCEPTION;
    }
    then_args[0] = undef_fn;
    result = JS_Invoke(ctx, promise, JS_ATOM_then, 1, vc(then_args));
    JS_FreeValue(ctx, undef_fn);
    JS_FreeValue(ctx, promise);
    return result;
}

static JSValue js_iterator_proto_iterator(JSContext *ctx, JSValueConst this_val,
                                          int argc, JSValueConst *argv)
{
    return js_dup(this_val);
}

static JSValue js_iterator_proto_get_toStringTag(JSContext *ctx, JSValueConst this_val)
{
    return JS_AtomToString(ctx, JS_ATOM_Iterator);
}

static JSValue js_iterator_proto_set_toStringTag(JSContext *ctx, JSValueConst this_val, JSValueConst val)
{
    int res;

    if (check_iterator(ctx, this_val) < 0)
        return JS_EXCEPTION;
    if (js_same_value(ctx, this_val, ctx->class_proto[JS_CLASS_ITERATOR]))
        return JS_ThrowTypeError(ctx, "Cannot assign to read only property");
    res = JS_GetOwnProperty(ctx, NULL, this_val, JS_ATOM_Symbol_toStringTag);
    if (res < 0)
        return JS_EXCEPTION;
    if (res) {
        if (JS_SetProperty(ctx, this_val, JS_ATOM_Symbol_toStringTag, js_dup(val)) < 0)
            return JS_EXCEPTION;
    } else {
        if (JS_DefinePropertyValueConst(ctx, this_val, JS_ATOM_Symbol_toStringTag, val, JS_PROP_C_W_E | JS_PROP_THROW) < 0)
            return JS_EXCEPTION;
    }
    return JS_UNDEFINED;
}

/* Iterator.prototype.{drop,take,map,filter,flatMap}: create the helper object over `this` (the source iterator).
   No drive-to-completion — pure object creation; the source is iterated lazily by the helper's .next(). */
/* IfAbruptCloseIterator: close the source. A GENERATOR source's .return() must run its finally on the tramp
   (js_generator_next is a DFAIL) — DEFER it to the interpreter caller via ctx->pending_close_gen, which its
   exception label routes onto do_generator_tramp. A non-generator source's .return() is a plain call — close now.
   Shared by the body's own failures and by the coerce-then-compute machine's abrupt-coercion hook, because the
   spec makes no distinction between them: step 5 of take/drop closes for BOTH. */
static void js_iterator_helper_close(JSContext *ctx, JSValueConst this_val, int magic)
{
    if (JS_VALUE_GET_TAG(this_val) == JS_TAG_OBJECT) {
        JSObject *tp = JS_VALUE_GET_OBJ(this_val);
        if (tp->class_id == JS_CLASS_GENERATOR && tp->u.generator_data
            && ((JSGeneratorData *)tp->u.generator_data)->state != JS_GENERATOR_STATE_EXECUTING) {
            DCHECK(JS_IsUninitialized(ctx->pending_close_gen), "pending_close_gen already set — nested IfAbruptCloseIterator");
            ctx->pending_close_gen = js_dup(this_val);
            return;
        }
    }
    JS_IteratorClose(ctx, this_val, true);
}

/* 27.1.4.5/27.1.4.3 steps 1-2: the receiver must be an Object, and that TypeError precedes the limit's
   coercion AND does not close anything. */
static int js_iterator_helper_precheck(JSContext *ctx, JSValueConst this_val, int magic)
{
    return check_iterator(ctx, this_val);
}

static JSValue js_create_iterator_helper(JSContext *ctx, JSValueConst this_val,
                                         int argc, JSValueConst *argv, int magic)
{
    JSValueConst func;
    JSValue obj, method;
    int64_t count;
    JSIteratorHelperData *it;

    if (check_iterator(ctx, this_val) < 0)
        return JS_EXCEPTION;
    func = JS_UNDEFINED;
    count = 0;

    switch(magic) {
    case JS_ITERATOR_HELPER_KIND_DROP:
    case JS_ITERATOR_HELPER_KIND_TAKE:
        {
            JSValue v;
            double dlimit;
            v = JS_ToNumber(ctx, argv[0]);
            if (JS_IsException(v))
                goto fail;
            if (JS_ToFloat64(ctx, &dlimit, v)) {
                JS_FreeValue(ctx, v);
                goto fail;
            }
            if (isnan(dlimit)) {
                JS_FreeValue(ctx, v);
                goto range_error;
            }
            if (!isfinite(dlimit)) {
                JS_FreeValue(ctx, v);
                if (dlimit < 0)
                    goto range_error;
                else
                    count = MAX_SAFE_INTEGER;
            } else {
                v = JS_ToIntegerFree(ctx, v);
                if (JS_IsException(v))
                    goto fail;
                if (JS_ToInt64Free(ctx, &count, v))
                    goto fail;
            }
            if (count < 0)
                goto range_error;
        }
        break;
    case JS_ITERATOR_HELPER_KIND_FILTER:
    case JS_ITERATOR_HELPER_KIND_FLAT_MAP:
    case JS_ITERATOR_HELPER_KIND_MAP:
        {
            func = argv[0];
            if (check_function(ctx, func))
                goto fail;
        }
        break;
    default:
        abort();
        break;
    }

    method = JS_GetProperty(ctx, this_val, JS_ATOM_next);
    if (JS_IsException(method))
        goto fail;
    obj = JS_NewObjectClass(ctx, JS_CLASS_ITERATOR_HELPER);
    if (JS_IsException(obj)) {
        JS_FreeValue(ctx, method);
        goto fail;
    }
    it = js_malloc(ctx, sizeof(*it));
    if (!it) {
        JS_FreeValue(ctx, obj);
        JS_FreeValue(ctx, method);
        goto fail;
    }
    memset(it, 0, sizeof(*it));
    it->kind = magic;
    it->obj = js_dup(this_val);
    it->func = js_dup(func);
    it->next = method;
    it->inner = JS_UNDEFINED;
    it->inner_next = JS_UNDEFINED;
    it->cb_value = JS_UNDEFINED;
    it->count = count;
    it->executing = 0;
    it->done = 0;
    JS_SetOpaqueInternal(obj, it);
    return obj;
range_error:
    JS_ThrowRangeError(ctx, "must be positive");
fail:
    js_iterator_helper_close(ctx, this_val, magic);
    return JS_EXCEPTION;
}

/* Resumable driver for a lazy Iterator Helper's .next() over a GENERATOR source: `res` = the source .next()
   {value,done} from the previous tramp drive (UNINITIALIZED at the start; owned by this fn). On DONE *out receives
   the {value,done} to deliver. Returns 0 = DONE, 1 = DRIVE the source .next() again. DROP built (skip `count`, then
   pass values through); other kinds still use the plain-iterator js_iterator_helper_next path. */
/* IfAbruptCloseIterator: close a helper's SOURCE on an abrupt completion (mapper/predicate throw), PRESERVING the
   pending exception. A GENERATOR source closes on the tramp (the exception label drains pending_close_gen in
   close_exc mode, saving+restoring the exception); a plain source closes inline as a throw completion (its own
   return() error is ignored, spec-correct). Call with the pending exception set, then return -1. */
static void iter_helper_close_source_abrupt(JSContext *ctx, JSIteratorHelperData *it)
{
    if (JS_VALUE_GET_TAG(it->obj) == JS_TAG_OBJECT) {
        JSObject *srcp = JS_VALUE_GET_OBJ(it->obj);
        if (srcp->class_id == JS_CLASS_GENERATOR && srcp->u.generator_data
            && ((JSGeneratorData *)srcp->u.generator_data)->state != JS_GENERATOR_STATE_EXECUTING
            && JS_IsUninitialized(ctx->pending_close_gen)) {
            ctx->pending_close_gen = js_dup(it->obj);
            return;
        }
    }
    JS_IteratorClose(ctx, it->obj, true);
}

static int js_iter_helper_step(JSContext *ctx, JSIteratorHelperData *it, JSValue res, JSValue *out)
{
    *out = JS_UNDEFINED;
    switch (it->resume_pc) {
    case ITHP_START:   /* res is UNINITIALIZED — decide the first drive */
        switch (it->kind) {
        case JS_ITERATOR_HELPER_KIND_DROP:
            if (it->count > 0) { it->count--; it->resume_pc = ITHP_DROP_SKIP; }
            else it->resume_pc = ITHP_EMIT;
            return 1;
        case JS_ITERATOR_HELPER_KIND_TAKE:
            if (it->count == 0) {   /* limit reached: close the source (spec IteratorClose), then deliver done. */
                it->done = 1;
                if (tramp_gen_method_magic(it->next, it->obj) == GEN_MAGIC_NEXT) {
                    /* GENERATOR source: run its .return() (finally) on the tramp, then deliver {undefined,true} at
                       ITHP_TAKE_CLOSE. Never a drive-to-completion, never left suspended. */
                    it->drive_close = 1;
                    it->resume_pc = ITHP_TAKE_CLOSE;
                    return 1;
                }
                /* PLAIN / HELPER source: close inline, propagating its .return() throw. A helper chain that bottoms out
                   at a GENERATOR hits the js_generator_next DFAIL — the forcing function to route that close onto the
                   tramp too (not papered over). */
                if (JS_IteratorClose(ctx, it->obj, false)) return -1;
                *out = js_create_iterator_result(ctx, JS_UNDEFINED, true);
                return JS_IsException(*out) ? -1 : 0;
            }
            it->count--;
            it->resume_pc = ITHP_EMIT;
            return 1;
        case JS_ITERATOR_HELPER_KIND_MAP:
        case JS_ITERATOR_HELPER_KIND_FILTER:
            it->resume_pc = ITHP_EMIT;   /* drive the source; EMIT applies the callback */
            return 1;
        case JS_ITERATOR_HELPER_KIND_FLAT_MAP:
            if (!JS_IsUndefined(it->inner)) { it->drive_inner = 1; it->resume_pc = ITHP_FLATMAP_INNER; }   /* continue the active inner */
            else { it->drive_inner = 0; it->resume_pc = ITHP_FLATMAP_SRC; }   /* pull the next source value */
            return 1;
        default:
            DFAIL("js_iter_helper_step: kind not built on the tramp");
            return -1;
        }
    case ITHP_DROP_SKIP: {
        JSValue dv = JS_GetProperty(ctx, res, JS_ATOM_done);
        int d;
        if (JS_IsException(dv)) { JS_FreeValue(ctx, res); return -1; }
        d = JS_ToBoolFree(ctx, dv);
        JS_FreeValue(ctx, res);
        if (d) { it->done = 1; it->resume_pc = ITHP_START; *out = js_create_iterator_result(ctx, JS_UNDEFINED, true); return JS_IsException(*out) ? -1 : 0; }
        if (it->count > 0) { it->count--; return 1; }
        it->resume_pc = ITHP_EMIT;
        return 1;
    }
    case ITHP_TAKE_CLOSE:   /* take limit: the source's .return() (finally) ran on the tramp; discard it, deliver done */
        JS_FreeValue(ctx, res);
        it->resume_pc = ITHP_START;
        *out = js_create_iterator_result(ctx, JS_UNDEFINED, true);
        return JS_IsException(*out) ? -1 : 0;
    case ITHP_EMIT: {
        JSValue dv = JS_GetProperty(ctx, res, JS_ATOM_done);
        int d;
        if (JS_IsException(dv)) { JS_FreeValue(ctx, res); return -1; }
        d = JS_ToBoolFree(ctx, dv);
        if (d) { it->done = 1; it->resume_pc = ITHP_START; JS_FreeValue(ctx, res); *out = js_create_iterator_result(ctx, JS_UNDEFINED, true); return JS_IsException(*out) ? -1 : 0; }
        if (it->kind == JS_ITERATOR_HELPER_KIND_DROP || it->kind == JS_ITERATOR_HELPER_KIND_TAKE) {
            /* spec: value = IteratorValue(result) — READ .value (fires a value getter, may throw), then yield a fresh
               {value, done:false}; never pass the source result object through unread. */
            JSValue v = JS_GetProperty(ctx, res, JS_ATOM_value);
            JS_FreeValue(ctx, res);
            if (JS_IsException(v)) return -1;
            it->resume_pc = ITHP_START;
            *out = js_create_iterator_result(ctx, v, false);   /* consumes v */
            return JS_IsException(*out) ? -1 : 0;
        }
        /* MAP / FILTER: the callback must run ON THE TRAMP so a loop inside it parks like any other flow. Hold the
           source value on the helper and hand the call back to do_iter_helper_step (st==3); it re-enters here at
           ITHP_CB_DONE with the callback's result in `res`. */
        {
            JSValue v = JS_GetProperty(ctx, res, JS_ATOM_value);
            JS_FreeValue(ctx, res);
            if (JS_IsException(v)) { it->done = 1; return -1; }   /* IteratorStepValue threw: iterator is done, propagate */
            DCHECK(JS_IsUndefined(it->cb_value), "helper callback value already held — a step overlapped its callback");
            it->cb_value = v;
            it->resume_pc = ITHP_CB_DONE;
            return 3;   /* CALL it->func(v, count++) on the tramp */
        }
    }
    case ITHP_CB_DONE: {
        /* `res` is the map/filter callback's RESULT (it ran on the tramp). */
        {
            JSValue v = it->cb_value;
            JSValue fret = res;
            it->cb_value = JS_UNDEFINED;
            if (JS_IsException(fret)) {   /* IfAbruptCloseIterator: mapper/predicate threw -> close the source */
                JS_FreeValue(ctx, v);
                it->done = 1;
                iter_helper_close_source_abrupt(ctx, it);
                return -1;
            }
            if (it->kind == JS_ITERATOR_HELPER_KIND_MAP) {
                JS_FreeValue(ctx, v);
                it->resume_pc = ITHP_START;
                *out = js_create_iterator_result(ctx, fret, false);   /* consumes fret */
                return JS_IsException(*out) ? -1 : 0;
            }
            /* FILTER: emit v if the predicate is truthy, else skip and drive the source again. */
            if (JS_ToBoolFree(ctx, fret)) {
                it->resume_pc = ITHP_START;
                *out = js_create_iterator_result(ctx, v, false);   /* consumes v */
                return JS_IsException(*out) ? -1 : 0;
            }
            JS_FreeValue(ctx, v);
            it->resume_pc = ITHP_EMIT;   /* skip: re-drive the source, re-apply the predicate */
            return 1;
        }
    }
    case ITHP_FLATMAP_SRC: {
        /* res = SOURCE {value,done}. Map the value to an inner iterable, get its iterator, then drive the inner. */
        JSValue dv = JS_GetProperty(ctx, res, JS_ATOM_done);
        int d;
        if (JS_IsException(dv)) { JS_FreeValue(ctx, res); return -1; }
        d = JS_ToBoolFree(ctx, dv);
        if (d) { it->done = 1; it->resume_pc = ITHP_START; JS_FreeValue(ctx, res); *out = js_create_iterator_result(ctx, JS_UNDEFINED, true); return JS_IsException(*out) ? -1 : 0; }
        {
            JSValue v = JS_GetProperty(ctx, res, JS_ATOM_value);
            JS_FreeValue(ctx, res);
            if (JS_IsException(v)) { it->done = 1; return -1; }   /* IteratorStepValue threw: done, propagate (no close) */
            /* the mapper must run ON THE TRAMP (a loop inside it has to park): hold the element, hand the call to
               do_iter_helper_step, and resume at ITHP_FLATMAP_CB with its result. */
            DCHECK(JS_IsUndefined(it->cb_value), "flatMap mapper value already held");
            it->cb_value = v;
            it->resume_pc = ITHP_FLATMAP_CB;
            return 3;
        }
    }
    case ITHP_FLATMAP_CB: {
        {
            JSValue v = it->cb_value, mapped = res, method, iter;
            it->cb_value = JS_UNDEFINED;
            JS_FreeValue(ctx, v);
            /* IfAbruptCloseIterator on the mapper throw, a non-object result (GetIteratorFlattenable rejects it), and a
               throwing @@iterator: each closes the SOURCE preserving the exception. */
            if (JS_IsException(mapped)) { it->done = 1; iter_helper_close_source_abrupt(ctx, it); return -1; }
            if (!JS_IsObject(mapped)) { JS_FreeValue(ctx, mapped); JS_ThrowTypeError(ctx, "flatMap mapper did not return an object"); it->done = 1; iter_helper_close_source_abrupt(ctx, it); return -1; }
            method = JS_GetProperty(ctx, mapped, JS_ATOM_Symbol_iterator);
            if (JS_IsException(method)) { JS_FreeValue(ctx, mapped); it->done = 1; iter_helper_close_source_abrupt(ctx, it); return -1; }
            if (JS_IsNull(method) || JS_IsUndefined(method)) {
                JS_FreeValue(ctx, method);
                iter = mapped;   /* no [Symbol.iterator]: the mapped object IS the iterator */
            } else if (tramp_can_call_gen_create(method)) {
                /* the [Symbol.iterator] is a GENERATOR FUNCTION: creating the iterator runs its params-to-initial_yield,
                   which must be on the tramp (js_call_generator_function -> async_func_resume is off-tramp from here).
                   Stash (this=mapped, gfunc=method); do_iter_helper_step routes them onto do_generator_create_tramp. */
                it->inner = mapped;        /* the `this` for the create call (owned; transferred to the stack by the caller) */
                it->inner_next = method;   /* the generator function to call (owned) */
                return 2;                  /* CREATE_INNER */
            } else {
                iter = JS_GetIterator2(ctx, mapped, method);
                JS_FreeValue(ctx, method); JS_FreeValue(ctx, mapped);
                if (JS_IsException(iter)) return -1;
            }
            it->inner = iter;
            it->inner_next = JS_GetProperty(ctx, iter, JS_ATOM_next);
            if (JS_IsException(it->inner_next)) { JS_FreeValue(ctx, it->inner); it->inner = JS_UNDEFINED; it->inner_next = JS_UNDEFINED; return -1; }
            it->drive_inner = 1;
            it->resume_pc = ITHP_FLATMAP_INNER;
            return 1;   /* drive the inner iterator */
        }
    }
    case ITHP_FLATMAP_INNER: {
        /* res = INNER {value,done}. Emit each inner value; on inner exhaustion drop it and pull the next source value. */
        JSValue dv = JS_GetProperty(ctx, res, JS_ATOM_done);
        int d;
        if (JS_IsException(dv)) { JS_FreeValue(ctx, res); return -1; }
        d = JS_ToBoolFree(ctx, dv);
        if (d) {   /* inner exhausted: a naturally-done iterator needs no close; go back to the source */
            JS_FreeValue(ctx, res);
            JS_FreeValue(ctx, it->inner); it->inner = JS_UNDEFINED;
            JS_FreeValue(ctx, it->inner_next); it->inner_next = JS_UNDEFINED;
            it->drive_inner = 0;
            it->resume_pc = ITHP_FLATMAP_SRC;
            return 1;   /* drive the source for the next inner iterable */
        }
        it->resume_pc = ITHP_START;   /* the next .next() continues this inner (START re-checks it->inner) */
        *out = res;   /* emit the inner {value, done:false} */
        return 0;
    }
    }
    DFAIL("js_iter_helper_step: bad resume_pc");
    return -1;
}

/* Route a lazy Iterator Helper .next() whose SOURCE is a generator (the drive-to-completion case) and whose kind's
   tramp drive is built (DROP) onto do_iter_helper_tramp. Plain-iterator sources / other kinds stay on the C
   js_iterator_helper_next (a plain .next() call does not suspend). */
static bool tramp_can_call_iter_helper(JSValueConst func, JSValueConst this_val)
{
    JSObject *mp, *tp;
    JSIteratorHelperData *it;
    if (JS_VALUE_GET_TAG(func) != JS_TAG_OBJECT || JS_VALUE_GET_TAG(this_val) != JS_TAG_OBJECT) return false;
    mp = JS_VALUE_GET_OBJ(func);
    if (mp->class_id != JS_CLASS_C_FUNCTION || mp->u.cfunc.cproto != JS_CFUNC_iterator_next
        || mp->u.cfunc.c_function.iterator_next != js_iterator_helper_next
        || mp->u.cfunc.magic != GEN_MAGIC_NEXT) return false;
    tp = JS_VALUE_GET_OBJ(this_val);
    if (tp->class_id != JS_CLASS_ITERATOR_HELPER) return false;
    it = tp->u.iterator_helper_data;
    if (!it || it->executing || it->done) return false;
    return it->kind == JS_ITERATOR_HELPER_KIND_DROP || it->kind == JS_ITERATOR_HELPER_KIND_TAKE
        || it->kind == JS_ITERATOR_HELPER_KIND_MAP || it->kind == JS_ITERATOR_HELPER_KIND_FILTER
        || it->kind == JS_ITERATOR_HELPER_KIND_FLAT_MAP;   /* built (the step dispatches gen vs plain vs inner) */
}

static void js_iterator_helper_finalizer(JSRuntime *rt, JSValueConst val)
{
    JSObject *p = JS_VALUE_GET_OBJ(val);
    JSIteratorHelperData *it = p->u.iterator_helper_data;
    if (it) {
        JS_FreeValueRT(rt, it->obj);
        JS_FreeValueRT(rt, it->func);
        JS_FreeValueRT(rt, it->next);
        JS_FreeValueRT(rt, it->inner);
        JS_FreeValueRT(rt, it->inner_next);
        JS_FreeValueRT(rt, it->cb_value);
        js_free_rt(rt, it);
    }
}

static void js_iterator_helper_mark(JSRuntime *rt, JSValueConst val,
                                   JS_MarkFunc *mark_func)
{
    JSObject *p = JS_VALUE_GET_OBJ(val);
    JSIteratorHelperData *it = p->u.iterator_helper_data;
    if (it) {
        JS_MarkValue(rt, it->obj, mark_func);
        JS_MarkValue(rt, it->func, mark_func);
        JS_MarkValue(rt, it->next, mark_func);
        JS_MarkValue(rt, it->inner, mark_func);
        JS_MarkValue(rt, it->inner_next, mark_func);
        JS_MarkValue(rt, it->cb_value, mark_func);
    }
}

/* Plain-iterator (non-generator source) path for a lazy Iterator Helper .next(): a plain .next() call does not
   suspend, so a C loop here is NOT drive-to-completion. A GENERATOR source is routed onto the tramp before reaching
   here; one that slips through hits the js_generator_next DFAIL. Keeps the recognition identity. */
static JSValue js_iterator_helper_next(JSContext *ctx, JSValueConst this_val,
                                      int argc, JSValueConst *argv,
                                      int *pdone, int magic)
{
    /* The DRIVE runs on the tramp (do_iter_helper_tramp), recognized at the call site — the recognition declines
       (and this C entry runs) only for the TRIVIAL non-drive cases: a DONE helper (.next() -> {undefined,true}) and
       .return()/.throw() (close). Those iterate nothing, so no drive-to-completion. Any OTHER reason to be here is a
       source/kind whose tramp drive is not built — DFAIL, never a legacy C-loop fallback. */
    JSIteratorHelperData *it = JS_GetOpaque2(ctx, this_val, JS_CLASS_ITERATOR_HELPER);
    *pdone = false;
    if (!it) return JS_EXCEPTION;
    if (it->executing) {   /* GeneratorValidate: resuming a helper whose drive is already running (a source .next()
                              re-entered this helper) is a TypeError for every magic — a trivial guard, no drive. */
        return JS_ThrowTypeError(ctx, "Iterator Helper is already running");
    }
    if (magic == GEN_MAGIC_RETURN) {   /* .return(): close the source, mark done, return {value|undefined, done:true} */
        JSValue ret = (argc > 0) ? js_dup(argv[0]) : JS_UNDEFINED;
        if (!it->done) {
            it->done = 1;
            /* IteratorClose PROPAGATES a throw from GetMethod(return)/the return call — never swallow it. */
            if (JS_IteratorClose(ctx, it->obj, false)) { JS_FreeValue(ctx, ret); return JS_EXCEPTION; }
        }
        *pdone = true;
        return ret;
    }
    if (it->done) { *pdone = true; return JS_UNDEFINED; }   /* exhausted helper: .next() -> {undefined, done:true} */
    DFAIL("js_iterator_helper_next: helper source/kind not yet driven on the tramp — build do_iter_helper_step for it, never a legacy C-loop fallback");
    return JS_ThrowTypeError(ctx, "Iterator Helper .next() not on the tramp");
}



