/* Boolean */
static JSValue js_boolean_constructor(JSContext *ctx, JSValueConst new_target,
                                     int argc, JSValueConst *argv)
{
    JSValue val, obj;
    val = js_bool(JS_ToBool(ctx, argv[0]));
    if (!JS_IsUndefined(new_target)) {
        obj = js_create_from_ctor(ctx, new_target, JS_CLASS_BOOLEAN);
        if (!JS_IsException(obj))
            JS_SetObjectData(ctx, obj, val);
        return obj;
    } else {
        return val;
    }
}

static JSValue js_thisBooleanValue(JSContext *ctx, JSValueConst this_val)
{
    if (JS_VALUE_GET_TAG(this_val) == JS_TAG_BOOL)
        return js_dup(this_val);

    if (JS_VALUE_GET_TAG(this_val) == JS_TAG_OBJECT) {
        JSObject *p = JS_VALUE_GET_OBJ(this_val);
        if (p->class_id == JS_CLASS_BOOLEAN) {
            if (JS_VALUE_GET_TAG(p->u.object_data) == JS_TAG_BOOL)
                return p->u.object_data;
        }
    }
    return JS_ThrowTypeError(ctx, "not a boolean");
}

static JSValue js_boolean_toString(JSContext *ctx, JSValueConst this_val,
                                   int argc, JSValueConst *argv)
{
    JSValue val = js_thisBooleanValue(ctx, this_val);
    if (JS_IsException(val))
        return val;
    return JS_AtomToString(ctx, JS_VALUE_GET_BOOL(val) ?
                       JS_ATOM_true : JS_ATOM_false);
}

static JSValue js_boolean_valueOf(JSContext *ctx, JSValueConst this_val,
                                  int argc, JSValueConst *argv)
{
    return js_thisBooleanValue(ctx, this_val);
}

static const JSCFunctionListEntry js_boolean_proto_funcs[] = {
    JS_CFUNC_DEF("toString", 0, js_boolean_toString ),
    JS_CFUNC_DEF("valueOf", 0, js_boolean_valueOf ),
};

/* String */

static int js_string_get_own_property(JSContext *ctx,
                                      JSPropertyDescriptor *desc,
                                      JSValueConst obj, JSAtom prop)
{
    JSObject *p;
    JSString *p1;
    uint32_t idx, ch;

    /* This is a class exotic method: obj class_id is JS_CLASS_STRING */
    if (__JS_AtomIsTaggedInt(prop)) {
        p = JS_VALUE_GET_OBJ(obj);
        if (JS_VALUE_GET_TAG(p->u.object_data) == JS_TAG_STRING) {
            p1 = JS_VALUE_GET_STRING(p->u.object_data);
            idx = __JS_AtomToUInt32(prop);
            if (idx < p1->len) {
                if (desc) {
                    ch = string_get(p1, idx);
                    desc->flags = JS_PROP_ENUMERABLE;
                    desc->value = js_new_string_char(ctx, ch);
                    desc->getter = JS_UNDEFINED;
                    desc->setter = JS_UNDEFINED;
                }
                return true;
            }
        }
    }
    return false;
}

static int js_string_define_own_property(JSContext *ctx,
                                         JSValueConst this_obj,
                                         JSAtom prop, JSValueConst val,
                                         JSValueConst getter,
                                         JSValueConst setter, int flags)
{
    uint32_t idx;
    JSObject *p;
    JSString *p1, *p2;

    if (__JS_AtomIsTaggedInt(prop)) {
        idx = __JS_AtomToUInt32(prop);
        p = JS_VALUE_GET_OBJ(this_obj);
        if (JS_VALUE_GET_TAG(p->u.object_data) != JS_TAG_STRING)
            goto def;
        p1 = JS_VALUE_GET_STRING(p->u.object_data);
        if (idx >= p1->len)
            goto def;
        if (!check_define_prop_flags(JS_PROP_ENUMERABLE, flags))
            goto fail;
        /* check that the same value is configured */
        if (flags & JS_PROP_HAS_VALUE) {
            if (JS_VALUE_GET_TAG(val) != JS_TAG_STRING)
                goto fail;
            p2 = JS_VALUE_GET_STRING(val);
            if (p2->len != 1)
                goto fail;
            if (string_get(p1, idx) != string_get(p2, 0)) {
            fail:
                return JS_ThrowTypeErrorOrFalse(ctx, flags, "property is not configurable");
            }
        }
        return true;
    } else {
    def:
        return JS_DefineProperty(ctx, this_obj, prop, val, getter, setter,
                                 flags | JS_PROP_NO_EXOTIC);
    }
}

static int js_string_delete_property(JSContext *ctx,
                                     JSValueConst obj, JSAtom prop)
{
    uint32_t idx;

    if (__JS_AtomIsTaggedInt(prop)) {
        idx = __JS_AtomToUInt32(prop);
        if (idx < js_string_obj_get_length(ctx, obj)) {
            return false;
        }
    }
    return true;
}

static const JSClassExoticMethods js_string_exotic_methods = {
    .get_own_property = js_string_get_own_property,
    .define_own_property = js_string_define_own_property,
    .delete_property = js_string_delete_property,
};


/* No prologue: the machine's whole job is the coercion, so there is no stage 0 to write. */
static int js_str_ctor_step(JSContext *ctx, void *st, JSValue cb_result, JSValue **out_cb, int *out_argc)
{
    JSStrCtor *s = st;
    JSValueConst nt = s->hdr.this_val;   /* the receiver slot IS new_target here; UNDEFINED = a plain call */
    JSValueConst arg = step_arg(&s->hdr, 0);
    JSValue val, obj;

    if (!s->coerced && JS_VALUE_GET_TAG(arg) == JS_TAG_OBJECT) {
        s->coerced = 1;
        s->cb[0] = (JSValue)arg;   /* borrowed: the header holds the reference */
        *out_cb = s->cb; *out_argc = HINT_STRING;
        JS_FreeValue(ctx, cb_result);
        return 5;
    }
    if (s->coerced) {
        /* the coercion settled: a primitive, so ToString finishes without user code. */
        val = JS_ToString(ctx, cb_result);
        JS_FreeValue(ctx, cb_result);
    } else {
        JS_FreeValue(ctx, cb_result);
        if (s->hdr.argc == 0) {
            val = js_empty_string(ctx->rt);
        } else if (JS_IsUndefined(nt) && JS_IsSymbol(arg)) {
            /* 22.1.1.1 step 2.b: String(sym) describes the symbol; new String(sym) throws through ToString. */
            JSAtomStruct *p = JS_VALUE_GET_PTR(arg);
            val = JS_ConcatString3(ctx, "Symbol(", JS_AtomToString(ctx, js_get_atom_index(ctx->rt, p)), ")");
        } else {
            val = JS_ToString(ctx, arg);
        }
    }
    if (JS_IsException(val)) return -1;
    if (JS_IsUndefined(nt)) {
        s->result = val;
        return 0;
    }
    { JSString *p1 = JS_VALUE_GET_STRING(val);
      int len = p1->len;
      obj = js_create_from_ctor(ctx, nt, JS_CLASS_STRING);
      if (JS_IsException(obj)) { JS_FreeValue(ctx, val); return -1; }
      JS_SetObjectData(ctx, obj, val);
      JS_DefinePropertyValue(ctx, obj, JS_ATOM_length, js_int32(len), 0);
      s->result = obj; }
    return 0;
}

static JSValue js_str_ctor_fini(JSContext *ctx, void *st, bool take_result)
{
    JSStrCtor *s = st;
    JSValue r = take_result ? s->result : JS_UNDEFINED;
    if (!take_result) JS_FreeValue(ctx, s->result);
    js_free(ctx, s);
    return r;
}

static JSValue js_thisStringValue(JSContext *ctx, JSValueConst this_val)
{
    if (tag_is_string(JS_VALUE_GET_TAG(this_val)))
        return js_dup(this_val);

    if (JS_VALUE_GET_TAG(this_val) == JS_TAG_OBJECT) {
        JSObject *p = JS_VALUE_GET_OBJ(this_val);
        if (p->class_id == JS_CLASS_STRING) {
            if (JS_VALUE_GET_TAG(p->u.object_data) == JS_TAG_STRING)
                return js_dup(p->u.object_data);
        }
    }
    return JS_ThrowTypeError(ctx, "not a string");
}

static JSValue js_string_fromCharCode(JSContext *ctx, JSValueConst this_val,
                                      int argc, JSValueConst *argv)
{
    int i;
    StringBuffer b_s, *b = &b_s;

    // shortcut for single argument common case
    if (argc == 1 && JS_VALUE_GET_TAG(argv[0]) == JS_TAG_INT) {
        uint16_t c16 = JS_VALUE_GET_INT(argv[0]);
        return js_new_string_char(ctx, c16);
    }

    string_buffer_init(ctx, b, argc);

    for(i = 0; i < argc; i++) {
        int32_t c;
        if (JS_ToInt32(ctx, &c, argv[i]) || string_buffer_putc16(b, c & 0xffff)) {
            string_buffer_free(b);
            return JS_EXCEPTION;
        }
    }
    return string_buffer_end(b);
}

static JSValue js_string_fromCodePoint(JSContext *ctx, JSValueConst this_val,
                                       int argc, JSValueConst *argv)
{
    double d;
    int i, c;
    StringBuffer b_s, *b = NULL;

    // shortcut for single argument common case
    if (argc == 1 && JS_VALUE_GET_TAG(argv[0]) == JS_TAG_INT) {
        c = JS_VALUE_GET_INT(argv[0]);
        if (c < 0 || c > 0x10ffff)
            goto range_error;
        if (c <= 0xffff) {
            return js_new_string_char(ctx, c);
        } else {
            uint16_t c16[2];
            c16[0] = get_hi_surrogate(c);
            c16[1] = get_lo_surrogate(c);
            return js_new_string16_len(ctx, c16, 2);
        }
    }

    /* XXX: could pre-compute string length if all arguments are JS_TAG_INT */
    b = &b_s;
    if (string_buffer_init(ctx, b, argc))
        goto fail;
    for(i = 0; i < argc; i++) {
        if (JS_VALUE_GET_TAG(argv[i]) == JS_TAG_INT) {
            c = JS_VALUE_GET_INT(argv[i]);
            if (c < 0 || c > 0x10ffff)
                goto range_error;
        } else {
            if (JS_ToFloat64(ctx, &d, argv[i]))
                goto fail;
            if (!(d >= 0 && d <= 0x10ffff) || (c = (int)d) != d)
                goto range_error;
        }
        if (string_buffer_putc(b, c))
            goto fail;
    }
    return string_buffer_end(b);

 range_error:
    JS_ThrowRangeError(ctx, "invalid code point");
 fail:
    if (b) string_buffer_free(b);
    return JS_EXCEPTION;
}

static JSValue js_string_raw(JSContext *ctx, JSValueConst this_val,
                             int argc, JSValueConst *argv)
{
    // raw(temp,...a)
    JSValue cooked, val, raw;
    StringBuffer b_s, *b = &b_s;
    int64_t i, n;

    string_buffer_init(ctx, b, 0);
    raw = JS_UNDEFINED;
    cooked = JS_ToObject(ctx, argv[0]);
    if (JS_IsException(cooked))
        goto exception;
    raw = JS_ToObjectFree(ctx, JS_GetProperty(ctx, cooked, JS_ATOM_raw));
    if (JS_IsException(raw))
        goto exception;
    if (js_get_length64(ctx, &n, raw) < 0)
        goto exception;

    for (i = 0; i < n; i++) {
        val = JS_ToStringFree(ctx, JS_GetPropertyInt64(ctx, raw, i));
        if (JS_IsException(val))
            goto exception;
        string_buffer_concat_value_free(b, val);
        if (i < n - 1 && i + 1 < argc) {
            if (string_buffer_concat_value(b, argv[i + 1]))
                goto exception;
        }
    }
    JS_FreeValue(ctx, cooked);
    JS_FreeValue(ctx, raw);
    return string_buffer_end(b);

exception:
    JS_FreeValue(ctx, cooked);
    JS_FreeValue(ctx, raw);
    string_buffer_free(b);
    return JS_EXCEPTION;
}

/* only used in test262 */
JSValue js_string_codePointRange(JSContext *ctx, JSValueConst this_val,
                                 int argc, JSValueConst *argv)
{
    uint32_t start, end, i, n;
    StringBuffer b_s, *b = &b_s;

    if (JS_ToUint32(ctx, &start, argv[0]) ||
        JS_ToUint32(ctx, &end, argv[1]))
        return JS_EXCEPTION;
    end = min_uint32(end, 0x10ffff + 1);

    if (start > end) {
        start = end;
    }
    n = end - start;
    if (end > 0x10000) {
        n += end - max_uint32(start, 0x10000);
    }
    if (string_buffer_init2(ctx, b, n, end >= 0x100))
        return JS_EXCEPTION;
    for(i = start; i < end; i++) {
        string_buffer_putc(b, i);
    }
    return string_buffer_end(b);
}


static int string_cmp(JSString *p1, JSString *p2, int x1, int x2, int len);
static int JS_ToUTF32String(JSContext *ctx, uint32_t **pbuf, JSValue val1);
static JSValue JS_NewUTF32String(JSContext *ctx, const uint32_t *buf, int len);

/* JS_ToInt32Clamp(v, 0, len, 0)'s arithmetic once its ToInt32Sat half is a step. */
static int str_clamp(int64_t v, int len)
{
    if (v < 0) v = 0;
    else if (v > len) v = len;
    return (int)v;
}

static int js_str_recv_step(JSContext *ctx, void *st, JSValue cb_result, JSValue **out_cb, int *out_argc)
{
    JSStrRecv *s = st;
    JSString *p;
    int mode = s->hdr.arg;
    int r, a, b, len, idx, c;

    if (s->hdr.stage == 0) {
        if (s->hdr.str_phase == STR_PH_START) {
            /* A zeroed state holds the INTEGER 0 in every JSValue field — freeable, which is what makes
               driver-owned allocation sound, but NOT a sentinel anything may read. normalize() with no form
               left `arg` at that zero and then read it as a JSString. Every field this machine will read is
               given its sentinel here, before the first thing that can suspend. */
            s->str = JS_UNDEFINED; s->arg = JS_UNDEFINED; s->result = JS_UNDEFINED;
        }
        r = step_thisstring_run(ctx, &s->hdr, cb_result, &s->str, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->hdr.stage = 1;
    }
    if (s->hdr.stage == 1) {
        switch (mode) {
        case STRRECV_AT: case STRRECV_CODEPOINTAT: case STRRECV_SUBSTRING:
        case STRRECV_CHARAT: case STRRECV_CHARCODEAT:
            r = step_toint64_run(ctx, &s->hdr, step_arg(&s->hdr, 0), cb_result, &s->idx, out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
            break;
        case STRRECV_INDEXOF: case STRRECV_LASTINDEXOF:
            r = step_tostring_run(ctx, &s->hdr, step_arg(&s->hdr, 0), cb_result, &s->arg, out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
            break;
        case STRRECV_NORMALIZE:
            /* an absent or undefined form is NFC and coerces nothing. The UTF-32 conversion the C body did first
               runs no user code, so reading the form before it is not observable. `arg` staying UNDEFINED IS the
               answer to "was there a form", so the two places cannot disagree. */
            if (!JS_IsUndefined(step_arg(&s->hdr, 0))) {
                r = step_tostring_run(ctx, &s->hdr, s->hdr.argv[0], cb_result, &s->arg, out_cb, out_argc);
                cb_result = JS_UNDEFINED;
                if (r) return r < 0 ? -1 : r;
            }
            break;
        }
        s->hdr.stage = 2;
    }
    p = JS_VALUE_GET_STRING(s->str);
    len = p->len;
    if (s->hdr.stage == 2) {
        s->idx2 = len;
        s->dpos = 0;
        if (mode == STRRECV_SUBSTRING) {
            if (!JS_IsUndefined(step_arg(&s->hdr, 1))) {
                r = step_toint64_run(ctx, &s->hdr, s->hdr.argv[1], cb_result, &s->idx2, out_cb, out_argc);
                cb_result = JS_UNDEFINED;
                if (r) return r < 0 ? -1 : r;
            }
        } else if ((mode == STRRECV_INDEXOF || mode == STRRECV_LASTINDEXOF) && s->hdr.argc > 1) {
            if (mode == STRRECV_LASTINDEXOF) {
                r = step_tofloat64_run(ctx, &s->hdr, s->hdr.argv[1], cb_result, &s->dpos, out_cb, out_argc);
            } else {
                r = step_toint64_run(ctx, &s->hdr, s->hdr.argv[1], cb_result, &s->idx2, out_cb, out_argc);
            }
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
        }
        s->hdr.stage = 3;
    }
    JS_FreeValue(ctx, cb_result);

    if (mode <= STRRECV_TRIM_BOTH) {
        a = 0;
        b = len;
        if (mode & 1) while (a < len && lre_is_space(string_get(p, a))) a++;
        if (mode & 2) while (b > a && lre_is_space(string_get(p, b - 1))) b--;
        s->result = js_sub_string(ctx, p, a, b);
        return JS_IsException(s->result) ? (s->result = JS_UNDEFINED, -1) : 0;
    }
    /* the saturating int64 narrows to int exactly as JS_ToInt32Sat's clamp did */
    idx = (s->idx < INT32_MIN) ? INT32_MIN : (s->idx > INT32_MAX) ? INT32_MAX : (int)s->idx;
    if (mode == STRRECV_AT) {
        if (idx < 0) idx = len + idx;
        if (idx < 0 || idx >= len) { s->result = JS_UNDEFINED; return 0; }
        s->result = js_new_string_char(ctx, string_get(p, idx));
        return JS_IsException(s->result) ? (s->result = JS_UNDEFINED, -1) : 0;
    }
    if (mode == STRRECV_CHARAT || mode == STRRECV_CHARCODEAT) {
        /* 22.1.3.1 / 22.1.3.2: an out-of-range position is the empty string / NaN, never a throw. */
        if (idx < 0 || idx >= len) {
            s->result = (mode == STRRECV_CHARAT) ? js_empty_string(ctx->rt) : JS_NAN;
            return JS_IsException(s->result) ? (s->result = JS_UNDEFINED, -1) : 0;
        }
        c = string_get(p, idx);
        s->result = (mode == STRRECV_CHARAT) ? js_new_string_char(ctx, c) : js_int32(c);
        return JS_IsException(s->result) ? (s->result = JS_UNDEFINED, -1) : 0;
    }
    if (mode == STRRECV_CODEPOINTAT) {
        if (idx < 0 || idx >= len) { s->result = JS_UNDEFINED; return 0; }
        c = string_getc(p, &idx);
        s->result = js_int32(c);
        return 0;
    }
    if (mode == STRRECV_SUBSTRING) {
        /* JS_ToInt32Clamp(0, len, 0) on each index, then the pair is ordered */
        a = str_clamp(s->idx, len);
        b = JS_IsUndefined(step_arg(&s->hdr, 1)) ? len : str_clamp(s->idx2, len);
        s->result = js_sub_string(ctx, p, a < b ? a : b, a < b ? b : a);
        return JS_IsException(s->result) ? (s->result = JS_UNDEFINED, -1) : 0;
    }
    if (mode == STRRECV_INDEXOF || mode == STRRECV_LASTINDEXOF) {
        JSString *p1 = JS_VALUE_GET_STRING(s->arg);
        int v_len = p1->len, pos, start, stop, inc, i, ret = -1;
        if (mode == STRRECV_LASTINDEXOF) {
            pos = len - v_len;
            if (s->hdr.argc > 1 && !isnan(s->dpos)) {
                if (s->dpos <= 0) pos = 0;
                else if (s->dpos < pos) pos = (int)s->dpos;
            }
            start = pos; stop = 0; inc = -1;
        } else {
            pos = (s->hdr.argc > 1) ? str_clamp(s->idx2, len) : 0;
            start = pos; stop = len - v_len; inc = 1;
        }
        if (len >= v_len && inc * (stop - start) >= 0) {
            for (i = start;; i += inc) {
                if (!string_cmp(p, p1, i, 0, v_len)) { ret = i; break; }
                if (i == stop) break;
            }
        }
        s->result = js_int32(ret);
        return 0;
    }
    DCHECK(mode == STRRECV_NORMALIZE, "string receiver machine: unknown mode");
    {
        UnicodeNormalizationEnum n_type = UNICODE_NFC;
        uint32_t *buf = NULL, *out_buf;
        int buf_len, out_len, is_compat;
        if (!JS_IsUndefined(s->arg)) {
            JSString *f = JS_VALUE_GET_STRING(s->arg);
            const char *form = JS_ToCString(ctx, s->arg), *q;
            size_t form_len = f->len;
            if (!form) return -1;
            q = form;
            is_compat = false;
            if (q[0] != 'N' || q[1] != 'F') goto bad_form;
            q += 2;
            if (*q == 'K') { is_compat = true; q++; }
            if ((*q != 'C' && *q != 'D') || (size_t)(q + 1 - form) != form_len) {
            bad_form:
                JS_FreeCString(ctx, form);
                JS_ThrowRangeError(ctx, "bad normalization form");
                return -1;
            }
            n_type = UNICODE_NFC + is_compat * 2 + (*q - 'C');
            JS_FreeCString(ctx, form);
        }
        buf_len = JS_ToUTF32String(ctx, &buf, s->str);   /* runs no user code */
        if (buf_len < 0) return -1;
        out_len = unicode_normalize(&out_buf, buf, buf_len, n_type,
                                    ctx->rt, (DynBufReallocFunc *)js_realloc_rt);
        js_free(ctx, buf);
        if (out_len < 0) return -1;
        s->result = JS_NewUTF32String(ctx, out_buf, out_len);
        js_free(ctx, out_buf);
        return JS_IsException(s->result) ? (s->result = JS_UNDEFINED, -1) : 0;
    }
}

static JSValue js_str_recv_fini(JSContext *ctx, void *st, bool take_result)
{
    JSStrRecv *s = st;
    JSValue r = take_result ? s->result : JS_UNDEFINED;
    if (!take_result) JS_FreeValue(ctx, s->result);
    JS_FreeValue(ctx, s->str);
    JS_FreeValue(ctx, s->arg);
    js_free(ctx, s);
    return r;
}


/* The all-strings fast path, kept because it is the common case: one allocation and memcpys instead of a chain
   of ToString + ConcatString. Returns 1 with *out set, or 0 when any operand is not a same-width string — in
   which case a ToPrimitive is due and only the step machine below can run it. */
static int js_string_concat_fast(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv, JSValue *out)
{
    int i, is_wide_char;
    JSString *p, *q;
    int64_t len;
    uint32_t n;
    char *d;

    if (JS_TAG_STRING != JS_VALUE_GET_TAG(this_val))
        return 0;
    p = JS_VALUE_GET_STRING(this_val);
    len = p->len;
    is_wide_char = p->is_wide_char;
    for (i = 0; i < argc; i++) {
        if (JS_TAG_STRING != JS_VALUE_GET_TAG(argv[i]))
            return 0;
        p = JS_VALUE_GET_STRING(argv[i]);
        if (p->is_wide_char ^ is_wide_char)
            return 0;
        len += p->len;
    }
    if (len > INT_MAX>>is_wide_char) {
        *out = JS_ThrowOutOfMemory(ctx);
        return 1;
    }
    p = JS_VALUE_GET_STRING(this_val);
    if (p->len == len) {
        *out = js_dup(this_val);
        return 1;
    }
    q = js_alloc_string(ctx, len, is_wide_char);
    if (!q) { *out = JS_EXCEPTION; return 1; }
    d = strv(q);
    n = p->len << is_wide_char;
    memcpy(d, strv(p), n);
    d += n;
    for (i = 0; i < argc; i++) {
        p = JS_VALUE_GET_STRING(argv[i]);
        n = p->len << is_wide_char;
        memcpy(d, strv(p), n);
        d += n;
    }
    if (!is_wide_char)
        *d = '\0';
    *out = JS_MKPTR(JS_TAG_STRING, q);
    return 1;
}


/* The prologue is RequireObjectCoercible plus the all-strings fast path — no user code, but it still belongs in
   step 0 rather than in a phase that runs before the machine exists. */
static int js_str_concat_prologue(JSContext *ctx, JSStrConcat *s)
{
    if (JS_IsUndefined(s->hdr.this_val) || JS_IsNull(s->hdr.this_val)) {
        JS_ThrowTypeError(ctx, "cannot convert to object");   /* RequireObjectCoercible, step 1 */
        return -1;
    }
    if (js_string_concat_fast(ctx, s->hdr.this_val, s->hdr.argc, (JSValueConst *)s->hdr.argv, &s->acc)) {
        if (JS_IsException(s->acc)) { s->acc = JS_UNDEFINED; return -1; }
        s->this_done = 1; s->k = s->hdr.argc;   /* nothing to coerce: the first step finishes */
    }
    return 0;
}

static int js_str_concat_step(JSContext *ctx, void *st, JSValue cb_result, JSValue **out_cb, int *out_argc)
{
    JSStrConcat *s = st;
    JSValue v;

    if (s->hdr.stage == 0) {
        s->hdr.stage = 1;
        s->acc = JS_UNDEFINED;
        if (js_str_concat_prologue(ctx, s)) { JS_FreeValue(ctx, cb_result); return -1; }
    }
    if (JS_VALUE_GET_TAG(cb_result) != JS_TAG_UNINITIALIZED && !JS_IsUndefined(cb_result)) {
        /* a coercion settled: it is a PRIMITIVE, so ToString finishes it without user code. */
        JSValue str = JS_ToString(ctx, cb_result);
        JS_FreeValue(ctx, cb_result);
        if (JS_IsException(str)) return -1;
        if (!s->this_done) { s->this_done = 1; s->acc = str; }
        else { s->acc = JS_ConcatString(ctx, s->acc, str); s->k++;
               if (JS_IsException(s->acc)) { s->acc = JS_UNDEFINED; return -1; } }
    } else if (JS_VALUE_GET_TAG(cb_result) != JS_TAG_UNINITIALIZED) {
        JS_FreeValue(ctx, cb_result);
    }
    if (!s->this_done) {
        if (JS_VALUE_GET_TAG(s->hdr.this_val) == JS_TAG_OBJECT) {
            s->cb[0] = s->hdr.this_val;   /* borrowed: the header holds the reference */
            *out_cb = s->cb; *out_argc = HINT_STRING;
            return 5;
        }
        s->acc = JS_ToString(ctx, s->hdr.this_val);
        if (JS_IsException(s->acc)) { s->acc = JS_UNDEFINED; return -1; }
        s->this_done = 1;
    }
    while (s->k < s->hdr.argc) {
        v = s->hdr.argv[s->k];
        if (JS_VALUE_GET_TAG(v) == JS_TAG_OBJECT) {
            s->cb[0] = v;
            *out_cb = s->cb; *out_argc = HINT_STRING;
            return 5;
        }
        { JSValue str = JS_ToString(ctx, v);
          if (JS_IsException(str)) return -1;
          s->acc = JS_ConcatString(ctx, s->acc, str);
          if (JS_IsException(s->acc)) { s->acc = JS_UNDEFINED; return -1; }
          s->k++; }
    }
    return 0;
}

static JSValue js_str_concat_fini(JSContext *ctx, void *st, bool take_result)
{
    JSStrConcat *s = st;
    JSValue r = take_result ? s->acc : JS_UNDEFINED;
    if (!take_result) JS_FreeValue(ctx, s->acc);
    js_free(ctx, s);
    return r;
}

static int string_cmp(JSString *p1, JSString *p2, int x1, int x2, int len)
{
    int i, c1, c2;
    for (i = 0; i < len; i++) {
        if ((c1 = string_get(p1, x1 + i)) != (c2 = string_get(p2, x2 + i)))
            return c1 - c2;
    }
    return 0;
}

static int string_indexof_char(JSString *p, int c, int from)
{
    /* assuming 0 <= from <= p->len */
    int i, len = p->len;
    if (p->is_wide_char) {
        for (i = from; i < len; i++) {
            if (str16(p)[i] == c)
                return i;
        }
    } else {
        if ((c & ~0xff) == 0) {
            for (i = from; i < len; i++) {
                if (str8(p)[i] == (uint8_t)c)
                    return i;
            }
        }
    }
    return -1;
}

static int string_indexof(JSString *p1, JSString *p2, int from)
{
    /* assuming 0 <= from <= p1->len */
    int c, i, j, len1 = p1->len, len2 = p2->len;
    if (len2 == 0)
        return from;
    for (i = from, c = string_get(p2, 0); i + len2 <= len1; i = j + 1) {
        j = string_indexof_char(p1, c, i);
        if (j < 0 || j + len2 > len1)
            break;
        if (!string_cmp(p1, p2, j + 1, 1, len2 - 1))
            return j;
    }
    return -1;
}

static int64_t string_advance_index(JSString *p, int64_t index, bool unicode)
{
    if (!unicode || index >= p->len || !p->is_wide_char) {
        index++;
    } else {
        int index32 = (int)index;
        string_getc(p, &index32);
        index = index32;
    }
    return index;
}

static JSValue js_string_isWellFormed(JSContext *ctx, JSValueConst this_val,
                                      int argc, JSValueConst *argv)
{
    JSValue str;
    JSValue ret;
    JSString *p;
    uint32_t c, i, n;

    ret = JS_TRUE;
    str = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(str))
        return JS_EXCEPTION;

    p = JS_VALUE_GET_STRING(str);
    if (!p->is_wide_char || p->len == 0)
        goto done; // by definition well-formed

    for (i = 0, n = p->len; i < n; i++) {
        c = str16(p)[i];
        if (!is_surrogate(c))
            continue;
        if (is_lo_surrogate(c) || i + 1 == n)
            break;
        c = str16(p)[++i];
        if (!is_lo_surrogate(c))
            break;
    }

    if (i < n)
        ret = JS_FALSE;

done:
    JS_FreeValue(ctx, str);
    return ret;
}

static JSValue js_string_toWellFormed(JSContext *ctx, JSValueConst this_val,
                                      int argc, JSValueConst *argv)
{
    JSValue str;
    JSValue ret;
    JSString *p;
    uint32_t c, i, n;

    str = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(str))
        return JS_EXCEPTION;

    p = JS_VALUE_GET_STRING(str);
    if (!p->is_wide_char || p->len == 0)
        return str; // by definition well-formed

    // TODO(bnoordhuis) don't clone when input is well-formed
    ret = js_new_string16_len(ctx, str16(p), p->len);
    JS_FreeValue(ctx, str);
    if (JS_IsException(ret))
        return JS_EXCEPTION;

    p = JS_VALUE_GET_STRING(ret);
    for (i = 0, n = p->len; i < n; i++) {
        c = str16(p)[i];
        if (!is_surrogate(c))
            continue;
        if (is_lo_surrogate(c) || i + 1 == n) {
            str16(p)[i] = 0xFFFD;
            continue;
        }
        c = str16(p)[++i];
        if (!is_lo_surrogate(c))
            str16(p)[--i] = 0xFFFD;
    }

    return ret;
}


/* return < 0 if exception or true/false */
static int js_is_regexp(JSContext *ctx, JSValueConst obj);

static JSValue js_string_includes(JSContext *ctx, JSValueConst this_val,
                                  int argc, JSValueConst *argv, int magic)
{
    JSValue str, v = JS_UNDEFINED;
    int i, len, v_len, pos, start, stop, ret;
    JSString *p;
    JSString *p1;

    str = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(str))
        return str;
    ret = js_is_regexp(ctx, argv[0]);
    if (ret) {
        if (ret > 0)
            JS_ThrowTypeError(ctx, "regexp not supported");
        goto fail;
    }
    v = JS_ToString(ctx, argv[0]);
    if (JS_IsException(v))
        goto fail;
    p = JS_VALUE_GET_STRING(str);
    p1 = JS_VALUE_GET_STRING(v);
    len = p->len;
    v_len = p1->len;
    pos = (magic == 2) ? len : 0;
    if (argc > 1 && !JS_IsUndefined(argv[1])) {
        if (JS_ToInt32Clamp(ctx, &pos, argv[1], 0, len, 0))
            goto fail;
    }
    len -= v_len;
    ret = 0;
    if (magic == 0) {
        start = pos;
        stop = len;
    } else {
        if (magic == 1) {
            if (pos > len)
                goto done;
        } else {
            pos -= v_len;
        }
        start = stop = pos;
    }
    if (start >= 0 && start <= stop) {
        for (i = start;; i++) {
            if (!string_cmp(p, p1, i, 0, v_len)) {
                ret = 1;
                break;
            }
            if (i == stop)
                break;
        }
    }
 done:
    JS_FreeValue(ctx, str);
    JS_FreeValue(ctx, v);
    return js_bool(ret);

fail:
    JS_FreeValue(ctx, str);
    JS_FreeValue(ctx, v);
    return JS_EXCEPTION;
}

static int check_regexp_g_flag(JSContext *ctx, JSValueConst regexp)
{
    int ret;
    JSValue flags;

    ret = js_is_regexp(ctx, regexp);
    if (ret < 0)
        return -1;
    if (ret) {
        flags = JS_GetProperty(ctx, regexp, JS_ATOM_flags);
        if (JS_IsException(flags))
            return -1;
        if (JS_IsUndefined(flags) || JS_IsNull(flags)) {
            JS_ThrowTypeError(ctx, "cannot convert to object");
            return -1;
        }
        flags = JS_ToStringFree(ctx, flags);
        if (JS_IsException(flags))
            return -1;
        ret = string_indexof_char(JS_VALUE_GET_STRING(flags), 'g', 0);
        JS_FreeValue(ctx, flags);
        if (ret < 0) {
            JS_ThrowTypeError(ctx, "regexp must have the 'g' flag");
            return -1;
        }
    }
    return 0;
}

static JSValue js_string_match(JSContext *ctx, JSValueConst this_val,
                               int argc, JSValueConst *argv, int atom)
{
    // match(rx), search(rx), matchAll(rx)
    // atom is JS_ATOM_Symbol_match, JS_ATOM_Symbol_search, or JS_ATOM_Symbol_matchAll
    JSValueConst O = this_val, regexp = argv[0], args[2];
    JSValue matcher, S, rx, result, str;
    int args_len;

    if (JS_IsUndefined(O) || JS_IsNull(O))
        return JS_ThrowTypeError(ctx, "cannot convert to object");

    if (JS_IsObject(regexp)) {
        matcher = JS_GetProperty(ctx, regexp, atom);
        if (JS_IsException(matcher))
            return JS_EXCEPTION;
        if (atom == JS_ATOM_Symbol_matchAll) {
            if (check_regexp_g_flag(ctx, regexp) < 0) {
                JS_FreeValue(ctx, matcher);
                return JS_EXCEPTION;
            }
        }
        if (!JS_IsUndefined(matcher) && !JS_IsNull(matcher)) {
            return JS_CallFree(ctx, matcher, regexp, 1, &O);
        }
    }
    S = JS_ToString(ctx, O);
    if (JS_IsException(S))
        return JS_EXCEPTION;
    args_len = 1;
    args[0] = regexp;
    str = JS_UNDEFINED;
    if (atom == JS_ATOM_Symbol_matchAll) {
        str = js_new_string8(ctx, "g");
        if (JS_IsException(str))
            goto fail;
        args[args_len++] = str;
    }
    rx = JS_CallConstructor(ctx, ctx->regexp_ctor, args_len, args);
    JS_FreeValue(ctx, str);
    if (JS_IsException(rx)) {
    fail:
        JS_FreeValue(ctx, S);
        return JS_EXCEPTION;
    }
    result = JS_InvokeFree(ctx, rx, atom, 1, vc(&S));
    JS_FreeValue(ctx, S);
    return result;
}

static JSValue js_string___GetSubstitution(JSContext *ctx, JSValueConst this_val,
                                           int argc, JSValueConst *argv)
{
    // GetSubstitution(matched, str, position, captures, namedCaptures, rep)
    JSValueConst matched, str, captures, namedCaptures, rep;
    JSValue capture, name, s;
    uint32_t position, len, matched_len, captures_len;
    int i, j, j0, k, k1;
    int c, c1;
    StringBuffer b_s, *b = &b_s;
    JSString *sp, *rp;

    matched = argv[0];
    str = argv[1];
    captures = argv[3];
    namedCaptures = argv[4];
    rep = argv[5];

    if (!JS_IsString(rep) || !JS_IsString(str))
        return JS_ThrowTypeError(ctx, "not a string");

    sp = JS_VALUE_GET_STRING(str);
    rp = JS_VALUE_GET_STRING(rep);

    string_buffer_init(ctx, b, 0);

    captures_len = 0;
    if (!JS_IsUndefined(captures)) {
        if (js_get_length32(ctx, &captures_len, captures))
            goto exception;
    }
    if (js_get_length32(ctx, &matched_len, matched))
        goto exception;
    if (JS_ToUint32(ctx, &position, argv[2]) < 0)
        goto exception;

    len = rp->len;
    i = 0;
    for(;;) {
        j = string_indexof_char(rp, '$', i);
        if (j < 0 || j + 1 >= len)
            break;
        string_buffer_concat(b, rp, i, j);
        j0 = j++;
        c = string_get(rp, j++);
        if (c == '$') {
            string_buffer_putc8(b, '$');
        } else if (c == '&') {
            if (string_buffer_concat_value(b, matched))
                goto exception;
        } else if (c == '`') {
            string_buffer_concat(b, sp, 0, position);
        } else if (c == '\'') {
            string_buffer_concat(b, sp, position + matched_len, sp->len);
        } else if (c >= '0' && c <= '9') {
            k = c - '0';
            if (j < len) {
                c1 = string_get(rp, j);
                if (c1 >= '0' && c1 <= '9') {
                    /* This behavior is specified in ES6 and refined in ECMA 2019 */
                    /* ECMA 2019 does not have the extra test, but
                       Test262 S15.5.4.11_A3_T1..3 require this behavior */
                    k1 = k * 10 + c1 - '0';
                    if (k1 >= 1 && k1 < captures_len) {
                        k = k1;
                        j++;
                    }
                }
            }
            if (k >= 1 && k < captures_len) {
                s = JS_GetPropertyInt64(ctx, captures, k);
                if (JS_IsException(s))
                    goto exception;
                if (!JS_IsUndefined(s)) {
                    if (string_buffer_concat_value_free(b, s))
                        goto exception;
                }
            } else {
                goto norep;
            }
        } else if (c == '<' && !JS_IsUndefined(namedCaptures)) {
            k = string_indexof_char(rp, '>', j);
            if (k < 0)
                goto norep;
            name = js_sub_string(ctx, rp, j, k);
            if (JS_IsException(name))
                goto exception;
            capture = JS_GetPropertyValue(ctx, namedCaptures, name);
            if (JS_IsException(capture))
                goto exception;
            if (!JS_IsUndefined(capture)) {
                if (string_buffer_concat_value_free(b, capture))
                    goto exception;
            }
            j = k + 1;
        } else {
        norep:
            string_buffer_concat(b, rp, j0, j);
        }
        i = j;
    }
    string_buffer_concat(b, rp, i, rp->len);
    return string_buffer_end(b);
exception:
    string_buffer_free(b);
    return JS_EXCEPTION;
}

/* String.prototype.replace / replaceAll with a FUNCTION replacer (22.1.3.19). The builtin holds a StringBuffer
   accumulator, endOfLastMatch and the is_first flag ACROSS each callback invocation, so it is continuation-holding:
   it cannot be call-site-unwrapped, and per §C-stack it stays in C while its callback dispatch is hooked into the
   flow machinery. Drives one match per step; replaceAll's loop is therefore preemptible at every callback boundary
   AND inside the callback body at every back-edge.
   Only the STRING-searchValue path lives here. An OBJECT searchValue dispatches to @@replace (a different function
   with a two-phase structure) and is deliberately NOT recognized — a separate step in its own right. */



/* 0 = DONE (s->result is the answer), 3 = CALL the replacer on the tramp, -1 = error.
   Mirrors the C loop exactly, split at the one point where it re-enters JS. */
static int js_str_replace_step(JSContext *ctx, JSStrReplace *s, JSValue cb_result)
{
    JSString *sp = JS_VALUE_GET_STRING(s->str);
    JSString *searchp = JS_VALUE_GET_STRING(s->search_str);

    if (s->cb_pending) {
        /* the replacer returned: ToString its result, then splice it in at the recorded position */
        JSValue repl = JS_ToString(ctx, cb_result);
        JS_FreeValue(ctx, cb_result);
        s->cb_pending = 0;
        if (JS_IsException(repl))
            return -1;
        string_buffer_concat(&s->b, sp, s->endOfLastMatch, s->pos);
        string_buffer_concat_value_free(&s->b, repl);
        s->endOfLastMatch = s->pos + searchp->len;
        s->is_first = 0;
        if (!s->is_replaceAll)
            goto finish;
    }
    for (;;) {
        if (unlikely(searchp->len == 0)) {
            if (s->is_first)
                s->pos = 0;
            else if (s->endOfLastMatch >= sp->len)
                s->pos = -1;
            else
                s->pos = s->endOfLastMatch + 1;
        } else {
            s->pos = string_indexof(sp, searchp, s->endOfLastMatch);
        }
        if (s->pos < 0) {
            if (s->is_first) {
                /* no match at all: the ORIGINAL string is returned untouched (not a rebuilt copy) */
                string_buffer_free(&s->b);
                s->result = js_dup(s->str);
                return 0;
            }
            break;
        }
        if (!s->functional) {
            /* same walk, different substitution SOURCE: GetSubstitution instead of a callback, spliced here and
               on to the next match. Not a separate no-callback body. */
            JSValueConst gargs[6];
            JSValue repl;
            gargs[0] = s->search_str; gargs[1] = s->str;    gargs[2] = js_int32(s->pos);
            gargs[3] = JS_UNDEFINED;  gargs[4] = JS_UNDEFINED; gargs[5] = s->rep_val;
            repl = js_string___GetSubstitution(ctx, JS_UNDEFINED, 6, gargs);
            if (JS_IsException(repl))
                return -1;
            string_buffer_concat(&s->b, sp, s->endOfLastMatch, s->pos);
            string_buffer_concat_value_free(&s->b, repl);
            s->endOfLastMatch = s->pos + searchp->len;
            s->is_first = 0;
            if (!s->is_replaceAll)
                goto finish;
            continue;
        }
        s->cb_args[0] = JS_UNDEFINED;                /* thisArgument */
        s->cb_args[2] = s->search_str;               /* borrowed: matched */
        s->cb_args[3] = js_int32(s->pos);            /* position */
        s->cb_args[4] = s->str;                      /* borrowed: the whole string */
        s->cb_pending = 1;
        return 3;
    }
finish:
    string_buffer_concat(&s->b, sp, s->endOfLastMatch, sp->len);
    s->result = string_buffer_end(&s->b);
    if (JS_IsException(s->result))
        return -1;
    return 0;
}

/* Recognized only when every operand is already a primitive of the right type: this_val a STRING (so no ToString
   side effect is skipped), searchValue a STRING (an object would dispatch to @@replace), and the replacer a plain
   bytecode function (a C/bound replacer has no preemptible body, so the ordinary path is already correct). */

/* String.prototype.replace/replaceAll IS a step machine. The @@replace dispatch below used to be a JS_CallFree
   straight out of C, which is exactly what kept "aaa".replace(/a/g, fn) driving to completion: the callee is
   itself a step builtin, so calling it from C ran its callbacks through an inline JS_Call that cannot suspend.
   The dispatch is now step code 3 — @@replace is invoked ON THE TRAMP like any other call — so the whole chain
   (str.replace -> @@replace -> the replacer) is preemptible end to end, and no recognizer is involved anywhere. */
static int js_str_replace_prologue(JSContext *ctx, JSStrReplace *s)
{
    JSValueConst this_val = s->hdr.this_val;
    JSValueConst searchValue = step_arg(&s->hdr, 0);
    JSValueConst repArg = step_arg(&s->hdr, 1);
    int is_replaceAll = s->hdr.arg;

    if (JS_IsUndefined(this_val) || JS_IsNull(this_val)) {
        JS_ThrowTypeError(ctx, "cannot convert to object");
        return -1;
    }
    s->is_replaceAll = is_replaceAll;

    if (JS_IsObject(searchValue)) {
        JSValue replacer;
        if (is_replaceAll && check_regexp_g_flag(ctx, searchValue) < 0) return -1;
        replacer = JS_GetProperty(ctx, searchValue, JS_ATOM_Symbol_replace);
        if (JS_IsException(replacer)) return -1;
        if (!JS_IsUndefined(replacer) && !JS_IsNull(replacer)) {
            const JSTrampStepDef *isd = tramp_step_def_of(replacer);
            if (isd) {
                /* the BUILT-IN @@replace, which is itself a step machine. Calling it would mean a step builtin
                   invoking a step builtin — the inline JS_Call in the driver cannot suspend, which is exactly the
                   drive-to-completion being removed. DELEGATE instead: run that one machine directly, so the whole
                   str.replace -> @@replace -> replacer chain is a single preemptible walk. */
                JSValueConst iargv[2];
                void *inner;
                iargv[0] = this_val;   /* the subject */
                iargv[1] = repArg;     /* the replacer */
                inner = tramp_step_state_new(ctx, isd, searchValue, 2, iargv, replacer);
                JS_FreeValue(ctx, replacer);
                if (!inner) return -1;
                s->inner = inner;
                s->mode = 3;
                return 0;
            }
            /* a USER-DEFINED @@replace: an ordinary callable, invoked on the tramp like any other call */
            s->mode = 1;
            s->cb_args[0] = js_dup(searchValue);                     /* this = the searchValue */
            s->cb_args[1] = replacer;                                /* owned */
            s->cb_args[2] = js_dup(this_val);                        /* the subject */
            s->cb_args[3] = js_dup(repArg);
            return 0;
        }
        JS_FreeValue(ctx, replacer);
    }
    /* The plain string-search walk — ONE walk for both replacer kinds. A callable drives step-code 3; anything
       else is ToString'd once and fed to GetSubstitution inside the same loop. There is no separate no-callback
       body: that duplicate walk is deleted. */
    /* The three ToStrings run the page's coercion methods, and this prologue is not a step — it cannot suspend.
       They are stages 10..12 of the machine instead; `mode` staying 4 is what tells the vstep to run them. */
    s->functional = JS_IsFunction(ctx, repArg);
    if (s->functional)
        s->cb_args[1] = js_dup(repArg);
    s->mode = 4;
    return 0;
}

static int js_str_replace_vstep(JSContext *ctx, void *st, JSValue cb_result, JSValue **out_cb, int *out_argc)
{
    JSStrReplace *s = st;
    int rr;
    if (s->hdr.stage == 0) {
        JS_FreeValue(ctx, cb_result);
        cb_result = JS_UNDEFINED;
        if (js_str_replace_prologue(ctx, s))
            return -1;
        s->hdr.stage = (s->mode == 4) ? 10 : 1;
    }
    /* 22.1.3.19 steps 3, 5 and 8: ToString on the receiver, the search value and — when it is not callable —
       the replacement. Each is the page's code, so each is its own stage. */
    if (s->hdr.stage == 10) {
        rr = step_tostring_run(ctx, &s->hdr, s->hdr.this_val, cb_result, &s->str, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (rr) return rr < 0 ? -1 : rr;
        s->hdr.stage = 11;
    }
    if (s->hdr.stage == 11) {
        rr = step_tostring_run(ctx, &s->hdr, step_arg(&s->hdr, 0), cb_result, &s->search_str, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (rr) return rr < 0 ? -1 : rr;
        s->hdr.stage = 12;
    }
    if (s->hdr.stage == 12) {
        if (!s->functional) {
            rr = step_tostring_run(ctx, &s->hdr, step_arg(&s->hdr, 1), cb_result, &s->rep_val, out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (rr) return rr < 0 ? -1 : rr;
        }
        string_buffer_init(ctx, &s->b, 0);
        s->is_first = 1;
        s->mode = 0;
        s->hdr.stage = 1;
    }
    if (s->mode == 3)   /* delegated: the built-in @@replace machine IS the walk */
        return ((JSStepHdr *)s->inner)->def->step(ctx, s->inner, cb_result, out_cb, out_argc);
    if (s->mode == 2)
        return 0;
    if (s->mode == 1) {
        if (s->cb_pending) {          /* @@replace returned: its result IS the answer */
            s->result = cb_result;
            s->cb_pending = 0;
            return 0;
        }
        s->cb_pending = 1;
        *out_cb = s->cb_args; *out_argc = 2;
        return 3;
    }
    {   /* mode 0: the string-search walk, one match per step */
        int r = js_str_replace_step(ctx, s, cb_result);
        if (r == 3) { *out_cb = s->cb_args; *out_argc = 3; }
        return r;
    }
}

static JSValue js_str_replace_fini(JSContext *ctx, void *st, bool take_result)
{
    JSStrReplace *s = st;
    JSValue r;
    if (s->mode == 3) {
        DCHECK(s->inner != NULL, "str.replace mode 3 without a delegated machine");
        r = tramp_step_state_free(ctx, s->inner, take_result);
        JS_FreeValue(ctx, s->str); JS_FreeValue(ctx, s->search_str);
        js_free(ctx, s);
        return r;
    }
    r = take_result ? s->result : JS_UNDEFINED;
    if (!take_result) JS_FreeValue(ctx, s->result);
    if (s->mode == 1) {
        JS_FreeValue(ctx, s->cb_args[0]); JS_FreeValue(ctx, s->cb_args[1]);
        JS_FreeValue(ctx, s->cb_args[2]); JS_FreeValue(ctx, s->cb_args[3]);
    } else if (s->mode == 0) {
        if (s->functional) JS_FreeValue(ctx, s->cb_args[1]);   /* the replacer dup'd by the prologue */
        if (s->b.ctx) string_buffer_free(&s->b);               /* unconsumed on the error path; NULL ctx = the
                                                                  prologue threw before string_buffer_init */
    }
    JS_FreeValue(ctx, s->str); JS_FreeValue(ctx, s->search_str); JS_FreeValue(ctx, s->rep_val);
    js_free(ctx, s);
    return r;
}


/* Stages: 0 the @@split GetMethod, 1 its dispatch, 2 ToString(receiver), 3 ToUint32(limit),
   4 ToString(separator), then the walk; 5 the @@split result. */
static int js_str_split_step(JSContext *ctx, void *st, JSValue cb_result, JSValue **out_cb, int *out_argc)
{
    JSStrSplit *s = st;
    JSValueConst O = s->hdr.this_val;
    JSValueConst separator = step_arg(&s->hdr, 0);
    JSValue A, T;
    JSString *sp, *rp;
    uint32_t lengthA;
    int64_t p, q, slen, rlen, e;
    int r;

    if (s->hdr.stage == 0) {
        JS_FreeValue(ctx, cb_result); cb_result = JS_UNDEFINED;
        s->str = JS_UNDEFINED; s->sep = JS_UNDEFINED; s->result = JS_UNDEFINED;
        if (JS_IsUndefined(O) || JS_IsNull(O)) {
            JS_ThrowTypeError(ctx, "cannot convert to object");
            return -1;
        }
        s->hdr.stage = 2;
        if (JS_IsObject(separator)) {
            s->hdr.stage = 1;
            s->hdr.cb_coerce[0] = (JSValue)separator;   /* borrowed: hdr.argv holds it */
            *out_cb = s->hdr.cb_coerce; *out_argc = (int)JS_ATOM_Symbol_split;
            return 6;
        }
    }
    if (s->hdr.stage == 1) {                 /* the @@split method arrived */
        JSValue m = cb_result;
        cb_result = JS_UNDEFINED;
        s->hdr.stage = 2;
        if (!JS_IsUndefined(m) && !JS_IsNull(m)) {
            s->cb[0] = js_dup(separator);    /* this = the separator */
            s->cb[1] = m;                    /* owned */
            s->cb[2] = js_dup(O);
            s->cb[3] = js_dup(step_arg(&s->hdr, 1));
            s->hdr.stage = 5;
            *out_cb = s->cb; *out_argc = 2;
            return 3;
        }
        JS_FreeValue(ctx, m);
    }
    if (s->hdr.stage == 5) {                 /* @@split's result IS the answer */
        s->result = cb_result;
        return 0;
    }
    if (s->hdr.stage == 2) {
        r = step_tostring_run(ctx, &s->hdr, O, cb_result, &s->str, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->hdr.stage = 3;
    }
    if (s->hdr.stage == 3) {
        s->lim32 = -1;                       /* the whole 32-bit range, i.e. 0xffffffff read unsigned */
        if (!JS_IsUndefined(step_arg(&s->hdr, 1))) {
            /* ToUint32 is ToInt32's wrap read unsigned, so one conversion serves both */
            r = step_toint32_run(ctx, &s->hdr, s->hdr.argv[1], cb_result, &s->lim32, out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
        }
        s->hdr.stage = 4;
    }
    if (s->hdr.stage == 4) {
        r = step_tostring_run(ctx, &s->hdr, separator, cb_result, &s->sep, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->hdr.stage = 6;
    }
    JS_FreeValue(ctx, cb_result);

    {   /* the walk: pure string scanning, no user code */
        uint32_t lim = (uint32_t)s->lim32;
        A = JS_NewArray(ctx);
        if (JS_IsException(A)) return -1;
        lengthA = 0;
        sp = JS_VALUE_GET_STRING(s->str);
        slen = sp->len;
        rp = JS_VALUE_GET_STRING(s->sep);
        rlen = rp->len;
        p = 0;
        if (lim == 0)
            goto done;
        if (JS_IsUndefined(separator))
            goto add_tail;
        if (slen == 0) {
            if (rlen != 0)
                goto add_tail;
            goto done;
        }
        for (q = p; (q += !rlen) <= slen - rlen - !rlen; q = p = e + rlen) {
            e = string_indexof(sp, rp, q);
            if (e < 0)
                break;
            T = js_sub_string(ctx, sp, p, e);
            if (JS_IsException(T)) goto fail;
            if (JS_CreateDataPropertyUint32(ctx, A, lengthA++, T, 0) < 0) goto fail;
            if (lengthA == lim)
                goto done;
        }
    add_tail:
        T = js_sub_string(ctx, sp, p, slen);
        if (JS_IsException(T)) goto fail;
        if (JS_CreateDataPropertyUint32(ctx, A, lengthA++, T, 0) < 0) goto fail;
    done:
        s->result = A;
        return 0;
    fail:
        JS_FreeValue(ctx, A);
        return -1;
    }
}

static JSValue js_str_split_fini(JSContext *ctx, void *st, bool take_result)
{
    JSStrSplit *s = st;
    JSValue r = take_result ? s->result : JS_UNDEFINED;
    int i;
    if (!take_result) JS_FreeValue(ctx, s->result);
    JS_FreeValue(ctx, s->str);
    JS_FreeValue(ctx, s->sep);
    for (i = 0; i < 4; i++) JS_FreeValue(ctx, s->cb[i]);
    js_free(ctx, s);
    return r;
}


static JSValue js_string_substr(JSContext *ctx, JSValueConst this_val,
                                int argc, JSValueConst *argv)
{
    JSValue str, ret;
    int a, len, n;
    JSString *p;

    str = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(str))
        return str;
    p = JS_VALUE_GET_STRING(str);
    len = p->len;
    if (JS_ToInt32Clamp(ctx, &a, argv[0], 0, len, len)) {
        JS_FreeValue(ctx, str);
        return JS_EXCEPTION;
    }
    n = len - a;
    if (!JS_IsUndefined(argv[1])) {
        if (JS_ToInt32Clamp(ctx, &n, argv[1], 0, len - a, 0)) {
            JS_FreeValue(ctx, str);
            return JS_EXCEPTION;
        }
    }
    ret = js_sub_string(ctx, p, a, a + n);
    JS_FreeValue(ctx, str);
    return ret;
}

static JSValue js_string_slice(JSContext *ctx, JSValueConst this_val,
                               int argc, JSValueConst *argv)
{
    JSValue str, ret;
    int len, start, end;
    JSString *p;

    str = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(str))
        return str;
    p = JS_VALUE_GET_STRING(str);
    len = p->len;
    if (JS_ToInt32Clamp(ctx, &start, argv[0], 0, len, len)) {
        JS_FreeValue(ctx, str);
        return JS_EXCEPTION;
    }
    end = len;
    if (!JS_IsUndefined(argv[1])) {
        if (JS_ToInt32Clamp(ctx, &end, argv[1], 0, len, len)) {
            JS_FreeValue(ctx, str);
            return JS_EXCEPTION;
        }
    }
    ret = js_sub_string(ctx, p, start, max_int(end, start));
    JS_FreeValue(ctx, str);
    return ret;
}

static JSValue js_string_pad(JSContext *ctx, JSValueConst this_val,
                             int argc, JSValueConst *argv, int padEnd)
{
    JSValue str, v = JS_UNDEFINED;
    StringBuffer b_s, *b = &b_s;
    JSString *p, *p1 = NULL;
    int n, len, c = ' ';

    str = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(str))
        goto fail1;
    if (JS_ToInt32Sat(ctx, &n, argv[0]))
        goto fail2;
    p = JS_VALUE_GET_STRING(str);
    len = p->len;
    if (len >= n)
        return str;
    if (argc > 1 && !JS_IsUndefined(argv[1])) {
        v = JS_ToString(ctx, argv[1]);
        if (JS_IsException(v))
            goto fail2;
        p1 = JS_VALUE_GET_STRING(v);
        if (p1->len == 0) {
            JS_FreeValue(ctx, v);
            return str;
        }
        if (p1->len == 1) {
            c = string_get(p1, 0);
            p1 = NULL;
        }
    }
    if (n > JS_STRING_LEN_MAX) {
        JS_ThrowRangeError(ctx, "invalid string length");
        goto fail3;
    }
    if (string_buffer_init(ctx, b, n))
        goto fail3;
    n -= len;
    if (padEnd) {
        if (string_buffer_concat(b, p, 0, len))
            goto fail;
    }
    if (p1) {
        while (n > 0) {
            int chunk = min_int(n, p1->len);
            if (string_buffer_concat(b, p1, 0, chunk))
                goto fail;
            n -= chunk;
        }
    } else {
        if (string_buffer_fill(b, c, n))
            goto fail;
    }
    if (!padEnd) {
        if (string_buffer_concat(b, p, 0, len))
            goto fail;
    }
    JS_FreeValue(ctx, v);
    JS_FreeValue(ctx, str);
    return string_buffer_end(b);

fail:
    string_buffer_free(b);
fail3:
    JS_FreeValue(ctx, v);
fail2:
    JS_FreeValue(ctx, str);
fail1:
    return JS_EXCEPTION;
}

static JSValue js_string_repeat(JSContext *ctx, JSValueConst this_val,
                                int argc, JSValueConst *argv)
{
    JSValue str;
    StringBuffer b_s, *b = &b_s;
    JSString *p;
    int64_t val;
    int n, len;

    str = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(str))
        goto fail;
    if (JS_ToInt64Sat(ctx, &val, argv[0]))
        goto fail;
    if (val < 0 || val > 2147483647) {
        JS_ThrowRangeError(ctx, "invalid repeat count");
        goto fail;
    }
    n = val;
    p = JS_VALUE_GET_STRING(str);
    len = p->len;
    if (len == 0 || n == 1)
        return str;
    if (val * len > JS_STRING_LEN_MAX) {
        JS_ThrowRangeError(ctx, "invalid string length");
        goto fail;
    }
    if (string_buffer_init2(ctx, b, n * len, p->is_wide_char))
        goto fail;
    if (len == 1) {
        string_buffer_fill(b, string_get(p, 0), n);
    } else {
        while (n-- > 0) {
            string_buffer_concat(b, p, 0, len);
        }
    }
    JS_FreeValue(ctx, str);
    return string_buffer_end(b);

fail:
    JS_FreeValue(ctx, str);
    return JS_EXCEPTION;
}


/* return 0 if before the first char */
static int string_prevc(JSString *p, int *pidx)
{
    int idx, c, c1;

    idx = *pidx;
    if (idx <= 0)
        return 0;
    idx--;
    if (p->is_wide_char) {
        c = str16(p)[idx];
        if (is_lo_surrogate(c) && idx > 0) {
            c1 = str16(p)[idx - 1];
            if (is_hi_surrogate(c1)) {
                c = from_surrogate(c1, c);
                idx--;
            }
        }
    } else {
        c = str8(p)[idx];
    }
    *pidx = idx;
    return c;
}

static bool test_final_sigma(JSString *p, int sigma_pos)
{
    int k, c1;

    /* before C: skip case ignorable chars and check there is
       a cased letter */
    k = sigma_pos;
    for(;;) {
        c1 = string_prevc(p, &k);
        if (!lre_is_case_ignorable(c1))
            break;
    }
    if (!lre_is_cased(c1))
        return false;

    /* after C: skip case ignorable chars and check there is
       no cased letter */
    k = sigma_pos + 1;
    for(;;) {
        if (k >= p->len)
            return true;
        c1 = string_getc(p, &k);
        if (!lre_is_case_ignorable(c1))
            break;
    }
    return !lre_is_cased(c1);
}

static int to_utf32_buf(JSContext *ctx, JSString *p, uint32_t **pbuf)
{
    uint32_t *b;
    int i, j, n;

    j = -1;
    n = p->len;
    b = js_malloc(ctx, max_int(1, n) * sizeof(*b));
    if (b)
        for (i = j = 0; i < n;)
            b[j++] = string_getc(p, &i);
    *pbuf = b;
    return j;
}

static JSValue js_string_localeCompare(JSContext *ctx, JSValueConst this_val,
                                       int argc, JSValueConst *argv)
{
    int i, n, an, bn, cmp;
    uint32_t *as, *bs, *ts;
    JSValue a, b, ret;

    ret = JS_EXCEPTION;
    as = NULL;
    bs = NULL;

    a = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(a))
        return JS_EXCEPTION;

    b = JS_ToString(ctx, argv[0]);
    if (JS_IsException(b))
        goto exception;

    an = to_utf32_buf(ctx, JS_VALUE_GET_STRING(a), &as);
    if (an == -1)
        goto exception;

    bn = to_utf32_buf(ctx, JS_VALUE_GET_STRING(b), &bs);
    if (bn == -1)
        goto exception;

    // TODO(bnoordhuis) skip normalization when input is latin1
    an = unicode_normalize(&ts, as, an, UNICODE_NFC, ctx,
                           (DynBufReallocFunc *)js_realloc);
    if (an == -1)
        goto exception;
    js_free(ctx, as);
    as = ts;

    // TODO(bnoordhuis) skip normalization when input is latin1
    bn = unicode_normalize(&ts, bs, bn, UNICODE_NFC, ctx,
                           (DynBufReallocFunc *)js_realloc);
    if (bn == -1)
        goto exception;
    js_free(ctx, bs);
    bs = ts;

    n = min_int(an, bn);
    for (i = 0; i < n; i++)
        if (as[i] != bs[i])
            break;
    if (i < n)
        cmp = compare_u32(as[i], bs[i]);
    else
        cmp = compare_u32(an, bn);
    ret = js_int32(cmp);

exception:
    JS_FreeValue(ctx, a);
    JS_FreeValue(ctx, b);
    js_free(ctx, as);
    js_free(ctx, bs);
    return ret;
}

static JSValue js_string_toLowerCase(JSContext *ctx, JSValueConst this_val,
                                     int argc, JSValueConst *argv, int to_lower)
{
    JSValue val;
    StringBuffer b_s, *b = &b_s;
    JSString *p;
    int i, c, j, l;
    uint32_t res[LRE_CC_RES_LEN_MAX];

    val = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(val))
        return val;
    p = JS_VALUE_GET_STRING(val);
    if (p->len == 0)
        return val;
    if (string_buffer_init(ctx, b, p->len))
        goto fail;
    for(i = 0; i < p->len;) {
        c = string_getc(p, &i);
        if (c == 0x3a3 && to_lower && test_final_sigma(p, i - 1)) {
            res[0] = 0x3c2; /* final sigma */
            l = 1;
        } else {
            l = lre_case_conv(res, c, to_lower);
        }
        for(j = 0; j < l; j++) {
            if (string_buffer_putc(b, res[j]))
                goto fail;
        }
    }
    JS_FreeValue(ctx, val);
    return string_buffer_end(b);
 fail:
    JS_FreeValue(ctx, val);
    string_buffer_free(b);
    return JS_EXCEPTION;
}

/* return (-1, NULL) if exception, otherwise (len, buf) */
static int JS_ToUTF32String(JSContext *ctx, uint32_t **pbuf, JSValue val1)
{
    JSValue val;
    int len;

    val = JS_ToString(ctx, val1);
    if (JS_IsException(val))
        return -1;
    len = to_utf32_buf(ctx, JS_VALUE_GET_STRING(val), pbuf);
    JS_FreeValue(ctx, val);
    return len;
}

static JSValue JS_NewUTF32String(JSContext *ctx, const uint32_t *buf, int len)
{
    int i;
    StringBuffer b_s, *b = &b_s;
    if (string_buffer_init(ctx, b, len))
        return JS_EXCEPTION;
    for(i = 0; i < len; i++) {
        if (string_buffer_putc(b, buf[i]))
            goto fail;
    }
    return string_buffer_end(b);
 fail:
    string_buffer_free(b);
    return JS_EXCEPTION;
}


/* also used for String.prototype.valueOf */
static JSValue js_string_toString(JSContext *ctx, JSValueConst this_val,
                                  int argc, JSValueConst *argv)
{
    return js_thisStringValue(ctx, this_val);
}

/* String Iterator */

static JSValue js_string_iterator_next(JSContext *ctx, JSValueConst this_val,
                                       int argc, JSValueConst *argv,
                                       int *pdone, int magic)
{
    JSArrayIteratorData *it;
    uint32_t idx, c, start;
    JSString *p;

    it = JS_GetOpaque2(ctx, this_val, JS_CLASS_STRING_ITERATOR);
    if (!it) {
        *pdone = false;
        return JS_EXCEPTION;
    }
    if (JS_IsUndefined(it->obj))
        goto done;
    p = JS_VALUE_GET_STRING(it->obj);
    idx = it->idx;
    if (idx >= p->len) {
        JS_FreeValue(ctx, it->obj);
        it->obj = JS_UNDEFINED;
    done:
        *pdone = true;
        return JS_UNDEFINED;
    }

    start = idx;
    c = string_getc(p, (int *)&idx);
    it->idx = idx;
    *pdone = false;
    if (c <= 0xffff) {
        return js_new_string_char(ctx, c);
    } else {
        return js_new_string16_len(ctx, str16(p) + start, 2);
    }
}

/* ES6 Annex B 2.3.2 etc. */
enum {
    magic_string_anchor,
    magic_string_big,
    magic_string_blink,
    magic_string_bold,
    magic_string_fixed,
    magic_string_fontcolor,
    magic_string_fontsize,
    magic_string_italics,
    magic_string_link,
    magic_string_small,
    magic_string_strike,
    magic_string_sub,
    magic_string_sup,
};

static JSValue js_string_CreateHTML(JSContext *ctx, JSValueConst this_val,
                                    int argc, JSValueConst *argv, int magic)
{
    JSValue str;
    JSString *p;
    StringBuffer b_s, *b = &b_s;
    static struct { const char *tag, *attr; } const defs[] = {
        { "a", "name" }, { "big", NULL }, { "blink", NULL }, { "b", NULL },
        { "tt", NULL }, { "font", "color" }, { "font", "size" }, { "i", NULL },
        { "a", "href" }, { "small", NULL }, { "strike", NULL },
        { "sub", NULL }, { "sup", NULL },
    };

    str = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(str))
        return JS_EXCEPTION;
    string_buffer_init(ctx, b, 7);
    string_buffer_putc8(b, '<');
    string_buffer_puts8(b, defs[magic].tag);
    if (defs[magic].attr) {
        // r += " " + attr + "=\"" + value + "\"";
        JSValue value;
        int i;

        string_buffer_putc8(b, ' ');
        string_buffer_puts8(b, defs[magic].attr);
        string_buffer_puts8(b, "=\"");
        value = JS_ToStringCheckObject(ctx, argv[0]);
        if (JS_IsException(value)) {
            JS_FreeValue(ctx, str);
            string_buffer_free(b);
            return JS_EXCEPTION;
        }
        p = JS_VALUE_GET_STRING(value);
        for (i = 0; i < p->len; i++) {
            int c = string_get(p, i);
            if (c == '"') {
                string_buffer_puts8(b, "&quot;");
            } else {
                string_buffer_putc16(b, c);
            }
        }
        JS_FreeValue(ctx, value);
        string_buffer_putc8(b, '\"');
    }
    // return r + ">" + str + "</" + tag + ">";
    string_buffer_putc8(b, '>');
    string_buffer_concat_value_free(b, str);
    string_buffer_puts8(b, "</");
    string_buffer_puts8(b, defs[magic].tag);
    string_buffer_putc8(b, '>');
    return string_buffer_end(b);
}

